window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-110"]=[{"id":"set2-mKOUNlPR","fingerprint":"ae9f4c82cb7d842c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile corecte cu privire la etiologia și impactul bolii parodontale?","options":[{"id":"A","text":"Netratată, crește riscul de dezvoltare a unor afecțiuni cardio-vasculare și respiratorii."},{"id":"B","text":"Induce o inflamație persistentă și excesivă a țesuturilor parodontale."},{"id":"C","text":"Este o infecție bacteriană, polimicrobiană, inițiată de biofilmul subgingival disbiotic."},{"id":"D","text":"Este o afecțiune strict localizată, fără impact sistemic demonstrat."},{"id":"E","text":"Majoritatea populației este rezistentă la boala parodontală, doar subiecții cu factori de risc fiind afectați."}],"correct":["A","B","C"],"pages":[299],"source":"set-2"},{"id":"set2-dxNalGe6","fingerprint":"c7026d58dc158b6e","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următorii factori sunt menționați ca modulatori ai rezistenței sau predispoziției față de distrucția parodontală?","options":[{"id":"A","text":"Consumul de alcool"},{"id":"B","text":"Factorii endocrini"},{"id":"C","text":"Tutunul"},{"id":"D","text":"Stresul"},{"id":"E","text":"Dieta bogată în carbohidrați"}],"correct":["B","C","D"],"pages":[299],"source":"set-2"},{"id":"set2-NVfPvras","fingerprint":"e576e5845470e2be","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce afirmație descrie corect biofilmul dentar și formarea sa?","options":[{"id":"A","text":"Limita dintre biofilmul supragingival și cel subgingival este reprezentată de marginea gingivală liberă."},{"id":"B","text":"Compoziția microbiană a biofilmului supragingival și a celui subgingival este identică."},{"id":"C","text":"Biofilmul dentar este un depozit neaderent, ușor de îndepărtat prin clătire."},{"id":"D","text":"Formarea biofilmului supragingival începe în treimea de mijloc a coroanei și migrează apoi în direcție apicală."},{"id":"E","text":"Suprafețele netede și lucioase favorizează acumularea biofilmului mai mult decât cele rugoase."}],"correct":["A"],"pages":[299],"source":"set-2"},{"id":"set2-9VbPV50D","fingerprint":"222b999d0b75f0ee","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Referitor la rata de formare a biofilmului dentar, care dintre următoarele afirmații este adevărată?","options":[{"id":"A","text":"Formarea este mai rapidă pe fețele palatinale decât pe cele vestibulare."},{"id":"B","text":"Rata de formare este mai rapidă în zona molară față de zona anterioară."},{"id":"C","text":"Ritmul de formare a plăcii este semnificativ mai accelerat la persoanele vârstnice față de cele tinere."},{"id":"D","text":"Rolul antibacterian al salivei este mai important decât rolul său de aport nutritiv în formarea plăcii."},{"id":"E","text":"Rata de formare este cu 50% mai mare în timpul nopții față de zi."}],"correct":["B"],"pages":[299],"source":"set-2"},{"id":"set2-RBMZA8dK","fingerprint":"2cf28a645582cf68","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele componente se regăsesc în matricea extracelulară a biofilmului dentar?","options":[{"id":"A","text":"Exclusiv componente organice, fără prezența ionilor anorganici."},{"id":"B","text":"Lipide rezultate din liza bacteriilor moarte."},{"id":"C","text":"Polizaharide de origine microbiană, precum dextranul și levanul."},{"id":"D","text":"Proteine provenite exclusiv din structura bacteriilor vii."},{"id":"E","text":"Imunoglobuline salivare."}],"correct":["B","C","E"],"pages":[299],"source":"set-2"},{"id":"set2-FQkw4QFN","fingerprint":"0be5b47a16cfd5f3","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce roluri îndeplinește matricea extracelulară a biofilmului dentar?","options":[{"id":"A","text":"Reprezintă o sursă de energie pentru bacteriile din comunitate."},{"id":"B","text":"Promovează desicarea bacteriilor pentru a le crește rezistența."},{"id":"C","text":"Asigură menținerea integrității biofilmului."},{"id":"D","text":"Asigură organizarea spațială a speciilor bacteriene unele față de altele."},{"id":"E","text":"Inhibă legarea substanțelor nutritive ionice."}],"correct":["A","C","D"],"pages":[299],"source":"set-2"},{"id":"set2-0_5w1dBd","fingerprint":"5ca0c8d8b2fe27c7","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este o caracteristică distinctivă a bacteriilor care cresc în comunitate (biofilm) comparativ cu cele în stare planctonică?","options":[{"id":"A","text":"Mediul specializat oferit de matricea extracelulară este identic cu mediul din suspensia lichidiană."},{"id":"B","text":"Nu există nicio diferență de comportament între bacteriile atașate (biofilm) și cele neatașate (planctonice)."},{"id":"C","text":"Bacteriile în stare planctonică, din fluidul crevicular, sunt conținute într-o matrice extracelulară densă."},{"id":"D","text":"Bacteriile din biofilm sunt mai puțin organizate spațial decât cele din starea planctonică."},{"id":"E","text":"Bacteriile din biofilm se comportă diferit față de aceleași bacterii care cresc în suspensie lichidiană."}],"correct":["E"],"pages":[299],"source":"set-2"},{"id":"set2-TpzODqPG","fingerprint":"d922c2684589b03c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce reprezintă disbioza în contextul inițierii parodontitei?","options":[{"id":"A","text":"O modificare a proporției bacteriilor subgingivale, implicând o scădere a numărului bacteriilor simbiotice și o posibilă creștere a proporției bacteriilor patogene."},{"id":"B","text":"Stabilizarea compoziției microbiene subgingivale, prevenind astfel apariția leziunilor."},{"id":"C","text":"Colonizarea exclusivă a șanțului gingival de către bacterii considerate în mod normal patogeni parodontali."},{"id":"D","text":"O creștere numerică egală atât pentru bacteriile simbiotice, cât și pentru cele patogene."},{"id":"E","text":"Eliminarea completă a florei microbiene comensale de la nivel subgingival."}],"correct":["A"],"pages":[300],"source":"set-2"},{"id":"set2-gl-Ke3KF","fingerprint":"bb66a068d0d00c61","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele variații locale pot influența compoziția microbiană în cavitatea orală?","options":[{"id":"A","text":"Variațiile locale de pH și temperatură."},{"id":"B","text":"Tipul de material din care sunt realizate obturațiile dentare."},{"id":"C","text":"Modificările hormonale asociate pubertății."},{"id":"D","text":"Erupția dentară."},{"id":"E","text":"Prezența cariilor sau a parodontitelor."}],"correct":["A","C","D","E"],"pages":[300],"source":"set-2"},{"id":"set2-e2tN0HQw","fingerprint":"77b683c6c16f577c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații despre colonizarea bacteriană a suprafețelor dentare sunt adevărate?","options":[{"id":"A","text":"Streptococii sunt primele bacterii care colonizează suprafețele dentare curate."},{"id":"B","text":"Bacteriile din genul Actinomyces și Veillonella sunt considerate colonizatori secundari."},{"id":"C","text":"Coagregarea interbacteriană asigură diversificarea comunității microbiene a plăcii."},{"id":"D","text":"Bacteriile pionier inhibă atașarea ulterioară a altor specii bacteriene."},{"id":"E","text":"Porphyromonas gingivalis este o bacterie pionier în formarea biofilmului dentar."}],"correct":["A","C"],"pages":[300],"source":"set-2"},{"id":"set2-hWuvCcJ3","fingerprint":"e7f4561b2536c74d","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Referitor la interacțiunile inhibitorii din biofilmul oral, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Bacteriocinele sunt produse exclusiv de bacteriile pionier pentru a preveni colonizarea secundară."},{"id":"B","text":"Anumite specii de streptococi produc peroxid de hidrogen, care inhibă creșterea lui Aggregatibacter actinomycetemcomitans."},{"id":"C","text":"Corelația inversă dintre Aggregatibacter actinomycetemcomitans și Streptococcus mutans se explică prin producția de peroxid de hidrogen de către S. mutans."},{"id":"D","text":"Producția de acizi organici de către Veillonella inhibă dezvoltarea streptococilor."},{"id":"E","text":"Aggregatibacter actinomycetemcomitans secretă o bacteriocină numită actinobacillină."}],"correct":["B","E"],"pages":[300],"source":"set-2"},{"id":"set2-khS-7oul","fingerprint":"8b4b94cb2de9f4e8","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile metabolice ale bacteriilor din placa dentară?","options":[{"id":"A","text":"Lactatul și formatul, produși de metabolismul streptococilor și al speciilor de Actinomyces, pot fi utilizați de Veillonella și Aggregatibacter actinomycetemcomitans."},{"id":"B","text":"Bacteriile predominante în placa matură sunt anaerobe și azaharolitice, utilizând aminoacizi și peptide mici ca nutrienți."},{"id":"C","text":"Toate bacteriile din biofilmul dentar, indiferent de stadiul de maturare, au un metabolism strict aerob."},{"id":"D","text":"Bacteriile colonizatoare inițiale, precum Streptococcus și Actinomyces spp, sunt în mare parte aerobe și folosesc zaharurile ca sursă de energie."},{"id":"E","text":"Porphyromonas gingivalis este o bacterie zaharolitică, dependentă de glucoza din fluidul sulcular."}],"correct":["A","B","D"],"pages":[300],"source":"set-2"},{"id":"set2-dX-YER5G","fingerprint":"357ab09c370f0317","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect interacțiunile metabolice care favorizează dezvoltarea Porphyromonas gingivalis?","options":[{"id":"A","text":"Campylobacter rectus produce protohem, un compus utilizat de Porphyromonas gingivalis."},{"id":"B","text":"Porphyromonas gingivalis utilizează acidul izobutiric produs de Treponema denticola pentru a se dezvolta."},{"id":"C","text":"Fusobacterium nucleatum poate crește pH-ul local prin sinteza de amoniac, creând un mediu favorabil pentru Porphyromonas gingivalis."},{"id":"D","text":"Streptococcus și Actinomyces produc lactat, care este principalul nutrient pentru Porphyromonas gingivalis."},{"id":"E","text":"Treponema denticola produce acid succinic, care este utilizat în metabolismul lui Porphyromonas gingivalis."}],"correct":["A","C","E"],"pages":[300],"source":"set-2"},{"id":"set2-YcGbi4HD","fingerprint":"1b5bf1c6c3df00c5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce se poate afirma despre rezistența la antibiotice a bacteriilor organizate în biofilm?","options":[{"id":"A","text":"Bacteriile din biofilm pot fi de până la 1000 de ori mai rezistente la antibiotice."},{"id":"B","text":"Rezistența la antibiotice este drastic crescută în biofilm comparativ cu bacteriile în stare planctonică."},{"id":"C","text":"Porphyromonas gingivalis în biofilm tolerează o concentrație de Metronidazol de 160 de ori mai mică decât în stare liberă."},{"id":"D","text":"Rezistența la antibiotice este identică, indiferent dacă bacteria se află în biofilm sau în stare planctonică."},{"id":"E","text":"Sinteza de polimeri extracelulari contribuie la protecția bacteriilor față de acțiunea substanțelor antimicrobiene."}],"correct":["A","B","E"],"pages":[300],"source":"set-2"},{"id":"set2-WYoMSn5i","fingerprint":"20ff05f38ceb2658","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele care contribuie la creșterea rezistenței la antibiotice a bacteriilor din biofilm?","options":[{"id":"A","text":"Eliminarea activă a antibioticului din celulă cu ajutorul pompelor de eflux."},{"id":"B","text":"Scăderea difuziunii antibioticului prin matricea extracelulară."},{"id":"C","text":"Sinteza unor enzime bacteriene precum β-lactamaza."},{"id":"D","text":"Creșterea accelerată a ratei de diviziune celulară, ducând la mutații favorabile."},{"id":"E","text":"Rata de creștere mai redusă a bacteriilor din biofilm."}],"correct":["A","B","C","E"],"pages":[301],"source":"set-2"},{"id":"set2-LpxJWH0W","fingerprint":"78ce745a3b2037e2","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce bacterii sunt componente ale complexului roșu, asociat cu pungile parodontale profunde?","options":[{"id":"A","text":"Treponema denticola"},{"id":"B","text":"Porphyromonas gingivalis"},{"id":"C","text":"Prevotella intermedia"},{"id":"D","text":"Tannerella forsythia"},{"id":"E","text":"Aggregatibacter actinomycetemcomitans"}],"correct":["A","B","D"],"pages":[301],"source":"set-2"},{"id":"set2-wSGqUOQj","fingerprint":"3460d3306f4800b0","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care afirmație descrie corect relația dintre complexul portocaliu și complexul roșu în colonizarea subgingivală?","options":[{"id":"A","text":"Complexul portocaliu și complexul roșu sunt ambele compatibile cu starea de sănătate parodontală."},{"id":"B","text":"Colonizarea cu bacterii din complexul roșu este o precondiție pentru dezvoltarea complexului portocaliu."},{"id":"C","text":"Cele două complexe sunt mutual exclusive și nu se regăsesc niciodată împreună în aceeași locație."},{"id":"D","text":"Speciile complexului portocaliu preced și favorizează colonizarea de către bacteriile complexului roșu."},{"id":"E","text":"Nu există o relație de succesiune sau asociere descrisă între cele două complexe."}],"correct":["D"],"pages":[301],"source":"set-2"},{"id":"set2-Y2RRQTtv","fingerprint":"a106c7f82227a8f0","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele caracteristici descriu corect Aggregatibacter actinomycetemcomitans (A.a)?","options":[{"id":"A","text":"Este capnofil, necesitând dioxid de carbon pentru creștere."},{"id":"B","text":"Este un cocobacil Gram-negativ, non-motil."},{"id":"C","text":"Este o bacterie asacharolitică."},{"id":"D","text":"Face parte din complexul bacterian galben."},{"id":"E","text":"Este un microorganism strict anaerob."}],"correct":["A","B"],"pages":[301],"source":"set-2"},{"id":"set2-kCD_Aadp","fingerprint":"b33c4d49229639b9","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care dintre următoarele argumente susține rolul major al Aggregatibacter actinomycetemcomitans (A.a) în parodontita agresivă localizată (PAL)?","options":[{"id":"A","text":"A.a este detectat mai frecvent în defectele supraosoase decât în cele infraosoase."},{"id":"B","text":"Majoritatea subiecților cu PAL prezintă un titru scăzut de anticorpi față de A.a."},{"id":"C","text":"PAL este considerată o monoinfecție cauzată exclusiv de A.a."},{"id":"D","text":"A.a este detectat mai frecvent la persoanele sănătoase decât la cele cu parodontită."},{"id":"E","text":"Tratamentele care au dus la eradicarea sa subgingivală au condus la îmbunătățiri clinice marcate."}],"correct":["E"],"pages":[301],"source":"set-2"},{"id":"set2-Y-CWB03g","fingerprint":"fd7f27a7a7393d21","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Comparativ cu bacteriile în stare planctonică, rezistența la antibiotice a bacteriilor din biofilm poate fi:","options":[{"id":"A","text":"Variabilă, dar niciodată mai mult de 100 de ori mai mare."},{"id":"B","text":"De 10 ori mai mică, datorită sinergiei comunitare."},{"id":"C","text":"De 160 de ori mai mare."},{"id":"D","text":"Identică, deoarece mecanismele de acțiune ale antibioticelor nu sunt afectate."},{"id":"E","text":"Până la 1000 de ori mai mare."}],"correct":["E"],"pages":[301],"source":"set-2"},{"id":"set2-DabjAWVD","fingerprint":"a51c4fe88fdf0a83","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care dintre următoarele complexe bacteriene sunt considerate compatibile cu starea de sănătate parodontală?","options":[{"id":"A","text":"Toate complexele, în funcție de concentrația bacteriană"},{"id":"B","text":"Doar complexul verde și galben"},{"id":"C","text":"Complexul portocaliu"},{"id":"D","text":"Complexul roșu"},{"id":"E","text":"Complexele violet, verde și galben"}],"correct":["E"],"pages":[301],"source":"set-2"},{"id":"set2-sRI5pmy6","fingerprint":"42d482bfdb7044d5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care sunt afirmațiile corecte referitoare la leucotoxina produsă de Aggregatibacter actinomycetemcomitans (A.a)?","options":[{"id":"A","text":"Clona JP2 a bacteriei produce cantități de leucotoxină similare cu celelalte clone."},{"id":"B","text":"Majoritatea sușelor de A.a produc cantități mari de leucotoxină, făcând detecția bacteriei un indicator cert de parodontită."},{"id":"C","text":"Acționează prin crearea de pori în membrana polimorfonuclearelor (PMN) și a unor populații de limfocite."},{"id":"D","text":"Funcția sa principală este sinteza de colagenaze pentru invazia țesutului gingival."},{"id":"E","text":"Protejează bacteria prin inhibarea imunității înnăscute de la nivelul parodonțiului."}],"correct":["C"],"pages":[302],"source":"set-2"},{"id":"set2-jzm-3ujP","fingerprint":"ae65bcd75834fb8d","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce implicații clinice sunt asociate cu prezența Aggregatibacter actinomycetemcomitans?","options":[{"id":"A","text":"Pierderea viitoare de atașament este corelată cu prezența A.a, indiferent de numărul de celule microbiene."},{"id":"B","text":"Nivelurile de A.a în placa subgingivală cresc semnificativ la aproximativ un an după apariția semnelor clinice de boală."},{"id":"C","text":"Eliminarea bacteriei din habitatul său este recomandată doar după apariția semnelor clare de parodontită."},{"id":"D","text":"Capacitatea sa de a invada țesutul gingival justifică luarea în considerare a terapiilor adjuvante de eradicare."},{"id":"E","text":"Persoanele purtătoare prezintă un risc mai mare de a dezvolta parodontită agresivă localizată (PAL)."}],"correct":["D","E"],"pages":[302],"source":"set-2"},{"id":"set2-GWyWd5km","fingerprint":"7d896529320a5386","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile Porphyromonas gingivalis?","options":[{"id":"A","text":"Formează colonii de culoare maro închis-negre."},{"id":"B","text":"Este detectat exclusiv în leziunile din parodontita agresivă localizată."},{"id":"C","text":"Este o specie dominantă în majoritatea leziunilor de parodontită cronică."},{"id":"D","text":"Este un coco-bacil Gram-pozitiv, strict anaerob."},{"id":"E","text":"Principalul său factor de virulență este o leucotoxină puternică."}],"correct":["A","C"],"pages":[302],"source":"set-2"},{"id":"set2-Oi2Nwl2S","fingerprint":"533f76399b4c1db5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce rol joacă Porphyromonas gingivalis ca patogen cheie în dezvoltarea parodontitei?","options":[{"id":"A","text":"Inhibă imunitatea înnăscută la nivelul parodonțiului, permițând modificarea creșterii biofilmului."},{"id":"B","text":"Eliminarea sa din biofilmul subgingival poate fi o țintă a terapiei parodontale."},{"id":"C","text":"Promovează relațiile homeostatice normale între flora microbiană și parodonțiu."},{"id":"D","text":"Produce leucotoxine care distrug direct prima linie de apărare a parodonțiului."},{"id":"E","text":"Susține și stabilizează restul florei microbiene asociate cu statusul de boală."}],"correct":["A","B","E"],"pages":[302],"source":"set-2"},{"id":"set2-CMBY59sr","fingerprint":"6a9d2ec36305573c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următorii sunt considerați factori de virulență ai bacteriilor subgingivale?","options":[{"id":"A","text":"Capacitatea de a stimula sistemul imun al organismului pentru a menține homeostazia."},{"id":"B","text":"Proteazele bacteriene."},{"id":"C","text":"Hidrogenul sulfurat și metil-mercaptanul, ca produși de metabolism."},{"id":"D","text":"Gingipainele, ca formă de lipopolizaharide."},{"id":"E","text":"Fimbriile bacteriene."}],"correct":["B","C","E"],"pages":[302],"source":"set-2"},{"id":"set2-pt9AgJ1V","fingerprint":"19d79a196e7d2bea","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce efect specific are metil-mercaptanul, un produs de metabolism al Porphyromonas gingivalis, asupra țesuturilor parodontale?","options":[{"id":"A","text":"Alterează metabolismul fibroblastelor."},{"id":"B","text":"Lărgește spațiile intercelulare ale epiteliului."},{"id":"C","text":"Inhibă imunitatea înnăscută la nivelul parodonțiului."},{"id":"D","text":"Acționează ca o colagenază, degradând fibrele de colagen."},{"id":"E","text":"Produce pori în membrana limfocitelor."}],"correct":["A","B"],"pages":[302],"source":"set-2"},{"id":"set2-dJ5qAjxB","fingerprint":"5a83ad43d9a4ae7c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care dintre următorii acizi, produși de metabolismul bacterian, are ca efect specific inducerea apoptozei fibroblastelor, a celulelor epiteliale gingivale și a limfocitelor B și T?","options":[{"id":"A","text":"Acidul hialuronic"},{"id":"B","text":"Acidul lactic"},{"id":"C","text":"Acidul propionic"},{"id":"D","text":"Acidul butiric"},{"id":"E","text":"Acidul acetic"}],"correct":["D"],"pages":[303],"source":"set-2"},{"id":"set2-hPxj_0pH","fingerprint":"4f7f4d1524a10950","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect funcțiile gingipainelor produse de Porphyromonas gingivalis?","options":[{"id":"A","text":"Sunt excrescențe externe ale membranei celulare care favorizează adeziunea."},{"id":"B","text":"Distrug factorul de necroză tumorală alfa (TNF-α)."},{"id":"C","text":"Degradează componente ale complementului, precum C3, C4, C5 și factorul B."},{"id":"D","text":"Sunt molecule formate dintr-o componentă lipidică (lipid A) și una polizaharidică."},{"id":"E","text":"Pot crește sinteza de interleukina-6 (IL-6) și IL-8 de către monocite."}],"correct":["B","C","E"],"pages":[303],"source":"set-2"},{"id":"set2-8fodkf23","fingerprint":"9e1399b9cfbc3249","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce roluri îndeplinesc fimbriile bacteriei Porphyromonas gingivalis în patogenia bolii parodontale?","options":[{"id":"A","text":"Protejează bacteria de fagocitoza mediată de complement."},{"id":"B","text":"Contribuie la adeziune prin interacțiunea cu proteine ale matricii extracelulare, cum ar fi colagenul și fibronectina."},{"id":"C","text":"Induc apoptoza fibroblastelor și a limfocitelor T și B."},{"id":"D","text":"Stimulează secreția de IL-6 și de IL-8."},{"id":"E","text":"Favorizează adeziunea bacteriei prin interacțiunea cu streptococii orali."}],"correct":["B","D","E"],"pages":[303],"source":"set-2"},{"id":"set2-N7sCOTkM","fingerprint":"bf9e6c1db484492c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce mecanisme utilizează bacteriile parodonto-patogene pentru a evita sistemul imun al gazdei?","options":[{"id":"A","text":"Invadarea celulelor epiteliale gingivale."},{"id":"B","text":"Producerea unei capsule polizaharidice extracelulare."},{"id":"C","text":"Utilizarea unui sistem proteolitic ce degradează componente ale sistemului imun."},{"id":"D","text":"Stimularea secreției de TNF-α pentru a inhiba activitatea monocitelor."},{"id":"E","text":"Interacțiunea specifică a lipopolizaharidelor cu limfocitele T pentru a le inactiva."}],"correct":["A","B","C"],"pages":[303],"source":"set-2"},{"id":"set2-Rk9KZaZX","fingerprint":"62040f12f18ba033","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care afirmație descrie corect invazia tisulară realizată de Porphyromonas gingivalis?","options":[{"id":"A","text":"Asigură o sursă directă de nutrienți prin liza celulelor epiteliale."},{"id":"B","text":"Reprezintă principalul mecanism de degradare a fibronectinei și colagenului."},{"id":"C","text":"Se consideră că invazia țesutului conjunctiv se produce în stadii mai avansate ale distrucției parodontale."},{"id":"D","text":"Justifică eficacitatea completă a terapiei mecanice subgingivale ca unică metodă de tratament."},{"id":"E","text":"Este un proces limitat strict la celulele epiteliale gingivale."}],"correct":["C"],"pages":[303],"source":"set-2"},{"id":"set2-g94yF2-G","fingerprint":"143e1d2a39ea2b32","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Referitor la lipopolizaharidele (LPZ) bacteriene, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Sunt localizate în membrana externă a bacteriilor Gram-negative."},{"id":"B","text":"Componenta lor principală este o cistein-proteinază denumită lipid A."},{"id":"C","text":"Sunt principalul factor de adeziune bacteriană la colagenul din matricea extracelulară."},{"id":"D","text":"Interacționează cu receptorii de pe suprafața celulelor imune, precum macrofagele și monocitele."},{"id":"E","text":"Declanșează eliberarea de mediatori proinflamatori de tipul citokinelor."}],"correct":["A","D","E"],"pages":[303],"source":"set-2"},{"id":"set2-Qh6QJoVD","fingerprint":"75965cdc8ea499b0","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt implicațiile clinice ale transmisiei și translocării bacteriilor parodonto-patogene?","options":[{"id":"A","text":"Stabilirea garantată a unei colonizări subgingivale permanente la translocarea prin sondă parodontală."},{"id":"B","text":"O semnificație clinică a modalităților de transmitere ce poate fi cuantificată cu precizie."},{"id":"C","text":"Periclitarea rezultatelor obținute prin terapia parodontală."},{"id":"D","text":"Crearea unei probleme epidemiologice prin transmiterea parodontitei de la o persoană la alta."},{"id":"E","text":"Colonizarea rapidă a regiunilor periimplantare, dinții acționând ca un rezervor bacterian."}],"correct":["C","D","E"],"pages":[304],"source":"set-2"},{"id":"set2-PaWLDDmY","fingerprint":"28e7fa66b41d120c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce factori pot perturba homeostazia microbiană a parodonțiului, conducând la disbioză?","options":[{"id":"A","text":"Fagocitarea microorganismelor de către neutrofile în condiții de sănătate."},{"id":"B","text":"Acumularea excesivă de placă subgingivală."},{"id":"C","text":"Factori de mediu precum fumatul și alimentația."},{"id":"D","text":"Modificări ale echilibrului hormonal, cum ar fi cele din timpul gravidității."},{"id":"E","text":"Infiltratul local neutrofilic caracteristic inflamației subclinice fiziologice."}],"correct":["B","C","D"],"pages":[304],"source":"set-2"},{"id":"set2-cxGYtQp2","fingerprint":"c0532a224eff8c9c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce modificări ale compoziției microbiotei subgingivale sunt observate în tranziția de la sănătate la parodontită?","options":[{"id":"A","text":"O modificare de la coci la bacili."},{"id":"B","text":"O trecere de la bacterii Gram-pozitive spre bacterii Gram-negative."},{"id":"C","text":"O predominanță a bacteriilor non-motile în detrimentul celor motile."},{"id":"D","text":"O tranziție de la bacterii facultativ anaerobe la bacterii strict anaerobe."},{"id":"E","text":"O schimbare de la specii proteolitice la specii fermentative."}],"correct":["A","B","D"],"pages":[304],"source":"set-2"},{"id":"set2-en9v3Wt3","fingerprint":"2bc07dbcc77735de","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este abordarea terapeutică principală pentru restabilirea homeostaziei microbiene subgingivale?","options":[{"id":"A","text":"Prevenirea apoptozei neutrofilelor pentru a menține un răspuns imun activ."},{"id":"B","text":"Reducerea sau eliminarea stimulului care a condus la disbioză."},{"id":"C","text":"Țintirea terapeutică specifică a anumitor specii bacteriene parodonto-patogene."},{"id":"D","text":"Stimularea inflamației locale pentru a crește fluxul crevicular."},{"id":"E","text":"Menținerea unei cantități totale crescute de placă bacteriană, dar cu o compoziție echilibrată."}],"correct":["B"],"pages":[304],"source":"set-2"},{"id":"set2-f12rPwhO","fingerprint":"9d8fb1a12755fa57","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce mecanisme caracterizează starea de sănătate parodontală și faza de rezoluție a inflamației fiziologice?","options":[{"id":"A","text":"Degranularea intra-tisulară a neutrofilelor pentru a elibera enzime litice."},{"id":"B","text":"Fagocitarea neutrofilelor apoptotice de către macrofage, ceea ce induce sinteza de lipoxine."},{"id":"C","text":"Suprimarea completă a recrutării de leucocite polimorfonucleare în sulcus."},{"id":"D","text":"Formarea unui infiltrat local neutrofilic ce controlează provocarea microbiană."},{"id":"E","text":"Intrarea neutrofilelor în apoptoză după fagocitarea microorganismelor."}],"correct":["B","D","E"],"pages":[304],"source":"set-2"},{"id":"set2-0DyTPUE3","fingerprint":"bff9376c221fbda1","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt principalele mecanisme implicate în patogeneza parodontitei?","options":[{"id":"A","text":"Un răspuns imuno-inflamator intens și necontrolat, declanșat de bacteriile subgingivale, duce la distrucția lentă a structurilor parodontale."},{"id":"B","text":"Distrucția parodontală se produce în principal prin mecanism direct, mediat de parodonto-patogeni individuali."},{"id":"C","text":"Celulele locale parodontale, precum neutrofilele și macrofagele, joacă un rol minor în procesul de distrucție."},{"id":"D","text":"Aportul exogen de resolvine reprezintă un factor cauzal în declanșarea bolii parodontale."},{"id":"E","text":"Reacțiile endogene de distrucție, inițiate de bacterii și produșii lor, constituie mecanismul predominant al leziunilor."}],"correct":["A","E"],"pages":[305],"source":"set-2"},{"id":"set2-7yFMoFWg","fingerprint":"e22e471e00567f46","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce efecte are prezența unei cantități mari de lipopolizaharide (LPZ) în țesuturile parodontale?","options":[{"id":"A","text":"Determină hipofuncționalitatea neutrofilelor recrutate în parodonțiu."},{"id":"B","text":"Crește riscul de eliberare extracelulară a conținutului enzimatic al neutrofilelor."},{"id":"C","text":"Accelerează apoptoza neutrofilelor, scurtând durata lor de viață în țesuturi."},{"id":"D","text":"Reglează reacțiile imuno-inflamatorii locale, limitând extinderea inflamației."},{"id":"E","text":"Stimulează celulele locale să sintetizeze cantități excesive și necontrolate de molecule proinflamatorii."}],"correct":["B","E"],"pages":[305],"source":"set-2"},{"id":"set2-cJ-X0FT3","fingerprint":"7049d740ae4e4c45","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele reprezintă caracteristici ale inflamației cronice parodontale?","options":[{"id":"A","text":"Întârzierea apoptozei neutrofilelor și degranularea lor intra-tisulară."},{"id":"B","text":"Supra-producția de mediatori proinflamatori (citokine) prin activare continuă."},{"id":"C","text":"O fază de rezoluție (stingere) a inflamației foarte eficientă."},{"id":"D","text":"Clearance-ul eficient al neutrofilelor în prezența microorganismelor subgingivale."},{"id":"E","text":"Sub-producția de radicali liberi, ducând la persistența bacteriană."}],"correct":["A","B"],"pages":[305],"source":"set-2"},{"id":"set2-e9ZgOnOq","fingerprint":"99ffc4a789ffbbf4","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile corecte cu privire la citokinele implicate în boala parodontală?","options":[{"id":"A","text":"În condiții de inflamație cronică, producția lor prelungită și excesivă conduce la distrucția parodontală."},{"id":"B","text":"Acționează prin fixarea pe receptorii celulelor țintă pentru a declanșa un răspuns biologic."},{"id":"C","text":"Toate citokinele implicate în inflamația parodontală au exclusiv efect proinflamator."},{"id":"D","text":"Mediază distrucția tisulară prin inhibarea sintezei de metaloproteinaze de către fibroblaste și osteoclaste."},{"id":"E","text":"Sunt polipeptide secretate exclusiv de celulele constitutive ale parodonțiului, precum fibroblastele."}],"correct":["A","B"],"pages":[305],"source":"set-2"},{"id":"set2-aya-n8a0","fingerprint":"306758a4b01ea5ce","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce rol specific au neutrofilele în cadrul proceselor patologice din boala parodontală?","options":[{"id":"A","text":"În prezența LPZ, apoptoza lor este accelerată, limitând astfel daunele colaterale."},{"id":"B","text":"Eliberarea extracelulară a conținutului lor enzimatic este un eveniment rar, fără potențial distructiv semnificativ."},{"id":"C","text":"Activitatea lor enzimatică și formarea de specii reactive de oxigen sunt diminuate."},{"id":"D","text":"Pot fi genetic hipofuncționale, ceea ce explică susceptibilitatea individuală la parodontită."},{"id":"E","text":"Recrutate în număr mare, devin hiperfuncționale sub acțiunea LPZ și secretă cantități excesive de mediatori pro-inflamatori."}],"correct":["E"],"pages":[305],"source":"set-2"},{"id":"set2-NSGH8RlQ","fingerprint":"5a402e1a385d7d5c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce molecule sunt menționate ca fiind o perspectivă pentru terapia adjuvantă a parodontitei, datorită rolului lor antiinflamator?","options":[{"id":"A","text":"Lipopolizaharide (LPZ), pentru a modula răspunsul imun."},{"id":"B","text":"Lipoxine, prin stimularea sintezei lor endogene."},{"id":"C","text":"Citokine, prin stimularea producției lor necontrolate."},{"id":"D","text":"Resolvine, prin aport exogen."},{"id":"E","text":"Metaloproteinaze, pentru a promova regenerarea tisulară."}],"correct":["B","D"],"pages":[305],"source":"set-2"},{"id":"set2-oZR-6t6O","fingerprint":"276764ac5425ebb1","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care sunt caracteristicile citokinelor în contextul distrucției parodontale?","options":[{"id":"A","text":"Mediază distrucția țesutului conjunctiv și a osului prin stimularea sintezei de metaloproteinaze de către fibroblaste și osteoclaste."},{"id":"B","text":"Sunt polipeptide secretate exclusiv de celule inflamatorii, precum neutrofilele și macrofagele."},{"id":"C","text":"Acționează prin inhibarea sintezei de proteine la nivelul celulelor țintă."},{"id":"D","text":"Sunt implicate exclusiv în răspunsul imuno-inflamator, fără a exista citokine cu efect antiinflamator."},{"id":"E","text":"Producția lor, indiferent de cantitate sau durată, are întotdeauna un rol protector în combaterea infecțiilor."}],"correct":["A"],"pages":[306],"source":"set-2"},{"id":"set2-Yiv24u__","fingerprint":"89caa6b72164382c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele sunt efecte directe ale Interleukinei-1β (IL-1β)?","options":[{"id":"A","text":"Inhibă diferențierea celulelor T helper."},{"id":"B","text":"Crește expresia moleculelor de adeziune ICAM la nivelul celulelor endoteliale."},{"id":"C","text":"Stimulează macrofagele să sintetizeze IL-6, care inhibă activarea limfocitelor B."},{"id":"D","text":"Are un efect antagonist cu prostaglandina E₂ (PGE₂)."},{"id":"E","text":"Stimulează celulele parodontale locale (fibroblaste, celule endoteliale, monocite) să secrete metaloproteinaze."}],"correct":["B","E"],"pages":[306],"source":"set-2"},{"id":"set2-09pFl--0","fingerprint":"9dc7347e2878cfc2","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce efecte sunt asociate cu Factorul de necroză tumorală-α (TNF-α) în patogeneza parodontitei?","options":[{"id":"A","text":"Promovează reparația tisulară locală."},{"id":"B","text":"Inhibă sinteza metaloproteinazelor."},{"id":"C","text":"Induce apoptoza fibroblastelor."},{"id":"D","text":"Activează osteoclastele, provocând resorbția osoasă."},{"id":"E","text":"Inhibă activitatea neutrofilelor și producția de IL-1β."}],"correct":["C","D"],"pages":[306],"source":"set-2"},{"id":"set2-eW9DEMAK","fingerprint":"3edb247cc8aed20c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce efect are inhibarea Prostaglandinei E₂ (PGE₂) de către antiinflamatoarele nesteroidiene?","options":[{"id":"A","text":"Favorizează dezvoltarea inflamației cronice persistente."},{"id":"B","text":"Sunt recomandate pentru administrare adjuvantă îndelungată în tratamentul parodontitei."},{"id":"C","text":"Stimulează faza de rezoluție a inflamației."},{"id":"D","text":"Potențează resorbția osoasă osteoclastică."},{"id":"E","text":"Cresc sinteza de metaloproteinaze de către celulele parodontale."}],"correct":["A"],"pages":[306],"source":"set-2"},{"id":"set2-AcmBKWO_","fingerprint":"561c56047545d739","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații despre metaloproteinaze (MMP) sunt corecte în contextul parodontal?","options":[{"id":"A","text":"MMP-8 și MMP-9 au o eficiență crescută în distrugerea colagenului de tip 1."},{"id":"B","text":"În țesuturile sănătoase, sunt produse în principal de neutrofile pentru menținerea homeostaziei."},{"id":"C","text":"Contribuie la inhibarea recrutării și activității osteoclastelor în parodontită."},{"id":"D","text":"Sunt o familie de endopeptidaze zinc-dependente responsabile de degradarea matricii extracelulare."},{"id":"E","text":"Metaloproteinaza-8 și metaloproteinaza-9 sunt eliberate în cantități mari de neutrofile în țesuturile inflamate."}],"correct":["A","D","E"],"pages":[306],"source":"set-2"},{"id":"set2-rq6RyQPP","fingerprint":"0d9842f0643ffa81","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Cum este descrisă relația dintre metaloproteinaze (MMP) și inhibitorii tisulari ai acestora (TIMP) în parodontită?","options":[{"id":"A","text":"Sinteza crescută de MMP stimulează o sinteză compensatorie de TIMP, care previne distrucția parodontală."},{"id":"B","text":"În parodontită, producția de TIMP depășește sinteza de MMP, ducând la fibroză tisulară."},{"id":"C","text":"Echilibrul dintre acțiunea MMP și TIMP se menține constant atât în sănătate, cât și în boală."},{"id":"D","text":"TIMP aderă de moleculele de MMP, inhibându-le activitatea, dar în parodontită capacitatea lor de neutralizare este depășită."},{"id":"E","text":"TIMP sunt activați de citokinele proinflamatorii pentru a limita distrucția tisulară."}],"correct":["D"],"pages":[306],"source":"set-2"},{"id":"set2-J9WHcR9h","fingerprint":"fe598caa3beb1e2b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care este procesul fundamental ce determină apariția semnelor clinice ale parodontitelor, precum pungile parodontale și mobilitatea dentară?","options":[{"id":"A","text":"Apariția recesiilor gingivale datorită periajului traumatic."},{"id":"B","text":"Hiperplazia epiteliului joncțional ca răspuns la stimularea LPZ."},{"id":"C","text":"Distrugerea ligamentelor parodontale și resorbția osului alveolar."},{"id":"D","text":"Migrarea secundară a dinților cauzată de forțe ocluzale excesive."},{"id":"E","text":"Pierderea atașamentului dintre dinte și structurile de susținere."}],"correct":["C","E"],"pages":[306],"source":"set-2"},{"id":"set2-IkB6IeVB","fingerprint":"fa82eba242991709","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele evenimente patofiziologice sunt implicate în formarea pungii parodontale adevărate ca urmare a agresiunii microbiene subgingivale?","options":[{"id":"A","text":"Distrugerea colagenului prin eliberarea necontrolată a enzimelor lizozomale din neutrofile."},{"id":"B","text":"Creșterea infiltratului inflamator gingival, în special neutrofilic."},{"id":"C","text":"Proliferarea epitelială compensatorie pentru menținerea intactă a barierei epiteliale."},{"id":"D","text":"Vasoconstricție și scăderea permeabilității vasculare în țesutul gingival."},{"id":"E","text":"Reducerea edemului gingival și superficializarea sulcusului gingival."}],"correct":["A","B","C"],"pages":[307],"source":"set-2"},{"id":"set2-t4NaNgqc","fingerprint":"97eeac29a457ceb5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce modificări tisulare caracterizează primele faze ale formării pungilor parodontale adevărate?","options":[{"id":"A","text":"Subțierea și ulcerarea epiteliului pungii și a celui de atașament."},{"id":"B","text":"Îngroșarea și keratinizarea epiteliului de atașament ca răspuns la agresiunea microbiană."},{"id":"C","text":"Detașarea celulelor din zona cea mai coronară a epiteliului joncțional."},{"id":"D","text":"Formarea unui nou atașament conjunctiv în porțiunea coronară a pungii."},{"id":"E","text":"Migrarea apicală a celulelor joncționale pentru a menține bariera epitelială."}],"correct":["A","C","E"],"pages":[307],"source":"set-2"},{"id":"set2-RB128rlm","fingerprint":"e42a77004655f89a","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"În contextul distrucției osoase alveolare din boala parodontală, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Mediatorii proinflamatori precum IL-1β, TNF-α și PGE₂ activează resorbția osoasă osteoclastică."},{"id":"B","text":"Procesul este inițiat indiferent de concentrația mediatorilor proinflamatori în țesutul gingival."},{"id":"C","text":"Distrucția osoasă este independentă de inflamația gingivală și de distrugerea ligamentului parodontal."},{"id":"D","text":"Resorbția osoasă se oprește la o înălțime de minim 2,5 mm între os și depozitul bacterian subgingival."},{"id":"E","text":"Este necesară persistența unei înălțimi de 0,5-1 mm de țesut conjunctiv neinflamat deasupra osului."}],"correct":["A","D","E"],"pages":[307],"source":"set-2"},{"id":"set2-yrzrUBkA","fingerprint":"2b5d93ca3331e81c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce rol specific îndeplinește osteoprotegerina în mecanismul de resorbție a osului alveolar?","options":[{"id":"A","text":"Antagonizează efectul RANKL, prevenind legarea acestuia de receptorul RANK."},{"id":"B","text":"Este un receptor de suprafață prezent pe celulele progenitoare osteoclastice."},{"id":"C","text":"Este un ligand care se leagă de osteoclastele mature pentru a le inactiva."},{"id":"D","text":"Se leagă direct de receptorul RANK, stimulând diferențierea osteoclastelor."},{"id":"E","text":"Crește expresia RANKL sub acțiunea citokinelor proinflamatorii."}],"correct":["A"],"pages":[307],"source":"set-2"},{"id":"set2-zOmKJVgt","fingerprint":"37fc285a953a448a","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele prin care factorii predispozanți locali contribuie la apariția bolilor parodontale?","options":[{"id":"A","text":"Crearea de zone de retenție pentru acumularea plăcii bacteriene."},{"id":"B","text":"Stimularea directă a diferențierii osteoclastelor prin eliberarea de mediatori specifici."},{"id":"C","text":"Întărirea fibrelor de colagen din ligamentul parodontal, ducând la rigidizarea acestuia."},{"id":"D","text":"Agresarea inserției epiteliale prin nerespectarea spațiului biologic."},{"id":"E","text":"Reducerea răspunsului imun local prin modificarea compoziției salivare."}],"correct":["A","D"],"pages":[307],"source":"set-2"},{"id":"set2-DaePcfJ0","fingerprint":"e8f0c6d526ad701b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele prin care factorii predispozanți locali reprezentați de tartru și anomaliile dento-maxilare acționează asupra parodonțiului?","options":[{"id":"A","text":"Nerespectarea spațiului biologic prin inserarea profundă a materialelor de obturație în șanțul gingival."},{"id":"B","text":"Reducerea conținutului de minerale din structura smalțului dentar."},{"id":"C","text":"Stimularea secreției de salivă cu pH acid."},{"id":"D","text":"Exercitarea de forțe necorespunzătoare ca aplitudine și direcție asupra dinților."},{"id":"E","text":"Crearea de zone de retenție pentru placa bacteriană."}],"correct":["D","E"],"pages":[308],"source":"set-2"},{"id":"set2-_IxHwQOs","fingerprint":"e1c1509eca30199c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce reprezintă tartrul dentar și care este principalul său rol în afectarea parodonțiului?","options":[{"id":"A","text":"Este un complex organo-mineral rezultat prin mineralizarea plăcii bacteriene, având rolul de suport și menținere a acesteia în contact cu țesutul gingival."},{"id":"B","text":"Este o afecțiune congenitală caracterizată prin depunerea de calciu pe suprafețele dentare."},{"id":"C","text":"Este o peliculă de natură exclusiv proteică ce împiedică remineralizarea smalțului."},{"id":"D","text":"Este o colorație extrinsecă a dinților, fără impact mecanic asupra gingiei."},{"id":"E","text":"Este o acumulare de resturi alimentare care produce direct liza țesutului gingival prin compuși acizi."}],"correct":["A"],"pages":[308],"source":"set-2"},{"id":"set2-JAtpLATw","fingerprint":"c8002c8b99bd3c1e","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile tartrului subgingival?","options":[{"id":"A","text":"Poate deveni supragingival în urma instalării retracției gingivale."},{"id":"B","text":"Prezintă o culoare ce variază de la brun închis la cenușiu."},{"id":"C","text":"Poate fi evidențiat prin explorare cu sonda."},{"id":"D","text":"Este situat coronar față de marginea gingivală și este ușor vizibil în cavitatea orală."},{"id":"E","text":"Este mai puțin aderent și mai moale decât tartrul supragingival."}],"correct":["A","B","C"],"pages":[308],"source":"set-2"},{"id":"set2-Wflj1LDF","fingerprint":"dfc4b696ac042045","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"În cât timp poate ajunge placa bacteriană la un grad de calcificare de 60-90%?","options":[{"id":"A","text":"10 săptămâni"},{"id":"B","text":"6 luni"},{"id":"C","text":"12 zile"},{"id":"D","text":"4-8 ore"},{"id":"E","text":"48 de ore"}],"correct":["C"],"pages":[308],"source":"set-2"},{"id":"set2-R1sreu_8","fingerprint":"870f7f7f952fcdb3","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care sunt zonele unde tartrul se depune cu predilecție, datorită apropierii de orificiile de deschidere ale glandelor salivare principale?","options":[{"id":"A","text":"Fețele palatinale ale frontalilor superiori și fețele linguale ale molarilor inferiori."},{"id":"B","text":"Fețele ocluzale ale premolarilor și fețele palatinale ale molarilor superiori."},{"id":"C","text":"Fețele vestibulare ale frontalilor inferiori și fețele linguale ale molarilor superiori."},{"id":"D","text":"Fețele proximale ale tuturor dinților, indiferent de arcadă."},{"id":"E","text":"Fețele linguale ale frontalilor inferiori și fețele vestibulare ale molarilor superiori."}],"correct":["E"],"pages":[308],"source":"set-2"},{"id":"set2-V8To3VPQ","fingerprint":"3b44326f86f2bc00","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următorii compuși fac parte din conținutul organic al tartrului dentar?","options":[{"id":"A","text":"Componente proteice (5,9-8,2%)."},{"id":"B","text":"Leucocite."},{"id":"C","text":"Componenta anorganică în proporție de 70-90%."},{"id":"D","text":"Carbohidrați (15-20%)."},{"id":"E","text":"Lipide (0,2%)."}],"correct":["A","B","E"],"pages":[308],"source":"set-2"},{"id":"set2-BT1HQvRl","fingerprint":"19f3718b742b9371","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce se întâmplă cu depunerea de tartru după atingerea unui nivel maxim, între 10 săptămâni și 6 luni?","options":[{"id":"A","text":"Rata de depunere se stabilizează și rămâne constantă pe viață."},{"id":"B","text":"Depunerea se accelerează exponențial."},{"id":"C","text":"Depunerea se reduce sub acțiunea mecanică limitantă a părților moi."},{"id":"D","text":"Tartrul începe un proces de autoliză și dispare treptat."},{"id":"E","text":"Compoziția tartrului se modifică, devenind exclusiv anorganică."}],"correct":["C"],"pages":[308],"source":"set-2"},{"id":"set2-qhCc1eJM","fingerprint":"6b49dd5cbfe7c9ce","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este afirmația corectă privind posibilitatea de îndepărtare a tartrului dentar?","options":[{"id":"A","text":"Tartrul subgingival este imposibil de îndepărtat, chiar și în cabinetul stomatologic."},{"id":"B","text":"Tartrul dentar, indiferent de localizare, este imposibil de îndepărtat de către pacient prin mijloace casnice."},{"id":"C","text":"Tartrul colorat de pigmenți alimentari este mai ușor de îndepărtat de către pacient."},{"id":"D","text":"Doar tartrul recent format (sub 12 zile) poate fi îndepărtat prin mijloace casnice."},{"id":"E","text":"Tartrul supragingival poate fi îndepărtat de pacient prin periaj viguros."}],"correct":["B"],"pages":[308],"source":"set-2"},{"id":"set2-i3yYgpki","fingerprint":"ac2cffb3b421c0b2","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la compoziția anorganică a tartrului supragingival sunt corecte?","options":[{"id":"A","text":"Hidroxiapatita constituie aproximativ două treimi din totalul componentei anorganice."},{"id":"B","text":"Fosfatul de calciu reprezintă componenta dominantă, cu un procent de aproximativ 76%."},{"id":"C","text":"Conține aproximativ 4% fosfat de magneziu și 3% carbonat de calciu."},{"id":"D","text":"Proteinele plasmatice sunt un component specific, diferențiindu-l de tartrul subgingival."},{"id":"E","text":"Whitlockita și brușita sunt singurele alte structuri cristaline prezente, pe lângă hidroxiapatită."}],"correct":["B","C"],"pages":[309],"source":"set-2"},{"id":"set2-icqgUCtD","fingerprint":"7ce7b9ef69f3a220","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce elemente caracterizează tartrul subgingival în comparație cu cel supragingival?","options":[{"id":"A","text":"Conține proteine salivare care sunt absente în tartrul supragingival."},{"id":"B","text":"Este compus în principal din carbonat de calciu."},{"id":"C","text":"Prezintă un conținut mai mare de sodiu și calciu."},{"id":"D","text":"Originea sa este saliva, spre deosebire de tartrul supragingival care provine din plasmă."},{"id":"E","text":"Procentul de hidroxiapatită este semnificativ mai redus."}],"correct":["C"],"pages":[309],"source":"set-2"},{"id":"set2-Ypl4obHS","fingerprint":"5fce04d7c4c5ab03","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile definitorii ale depozitului cunoscut sub numele de <i>materia alba</i>?","options":[{"id":"A","text":"Este formată din resturi alimentare fine, microorganisme și celule epiteliale descuamate."},{"id":"B","text":"Are o structură internă bine organizată, similară plăcii bacteriene."},{"id":"C","text":"Prezintă o aderență superioară plăcii bacteriene."},{"id":"D","text":"Compoziția sa include leucocite, precum și proteine și lipide salivare."},{"id":"E","text":"Este un depozit de consistență moale și culoare alb-gri."}],"correct":["A","D","E"],"pages":[309],"source":"set-2"},{"id":"set2-ztTTf-5M","fingerprint":"44c0c5e9a0b0f2a5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce consecințe are incongruența dento-alveolară cu înghesuire asupra parodonțiului?","options":[{"id":"A","text":"Determină lezarea directă a parodonțiului palatinal al frontalilor superiori de către incisivii inferiori."},{"id":"B","text":"Duce la absența autocurățirii în regiunea anterioară din cauza lipsei competenței labiale."},{"id":"C","text":"Favorizează retenția plăcii bacteriene și se poate însoți de o reducere a nivelului osos."},{"id":"D","text":"Produce aplatizarea papilelor interdentare, expunându-le impactului alimentar."},{"id":"E","text":"Septurile și papilele interdentare devin mai groase și mai rezistente la atacul bacterian."}],"correct":["C"],"pages":[309],"source":"set-2"},{"id":"set2-yZ6cqg3C","fingerprint":"e68d9b8aa2bd37ab","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"În cazul ocluziei deschise, care este mecanismul principal prin care se favorizează instalarea inflamației gingivale?","options":[{"id":"A","text":"Lezarea directă a parodonțiului de pe fața palatinală a frontalilor superiori."},{"id":"B","text":"Presiunea continuă exercitată de limba protrudată pe fețele linguale ale incisivilor."},{"id":"C","text":"Impactul alimentar direct asupra papilelor interdentare aplatizate."},{"id":"D","text":"Accentarea virulenței plăcii bacteriene deshidratate, ca urmare a lipsei competenței labiale și a autocurățirii."},{"id":"E","text":"Formarea unui parodonțiu fin, cu deficit de troficitate."}],"correct":["D"],"pages":[309],"source":"set-2"},{"id":"set2-4yNjiuHQ","fingerprint":"6c1c876f29e8de82","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele asocieri între anomalia dento-maxilară și efectul său asupra parodonțiului sunt corecte?","options":[{"id":"A","text":"Incongruența dento-alveolară cu spațiere - duce la formarea de septuri și papile interdentare subțiri, cu troficitate scăzută."},{"id":"B","text":"Ocluzia adâncă acoperită - favorizează depunerea de placă bacteriană pe suprafețe rugoase și anfractuoase."},{"id":"C","text":"Prognațiile mandibulare - pot conduce la vestibulo-versii ale incisivilor mandibulari și la un parodonțiu fin."},{"id":"D","text":"Compresiunea de maxilar - poate să apară recesii gingivale în zona frontală și demineralizări ale septurilor interdentare laterale."},{"id":"E","text":"Ectopiile dentare - pot cauza apariția de fenestrații sau dehiscente în timpul erupției."}],"correct":["C","D","E"],"pages":[309],"source":"set-2"},{"id":"set2-rYldS5Gg","fingerprint":"4b9e0b50063ac04b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Cum pot distrofiile dentare să contribuie la apariția inflamației parodontale?","options":[{"id":"A","text":"Prin inducerea unui traumatism ocluzal cauzat de ocluzia inversă frontală."},{"id":"B","text":"Prin conformarea unui parodonțiu fin, cu deficit de troficitate."},{"id":"C","text":"Prin suprafața rugoasă și marginile neregulate care favorizează depunerea de placă bacteriană în vecinătatea marginii gingivale."},{"id":"D","text":"Prin expunerea papilelor interdentare la impactul alimentar."},{"id":"E","text":"Prin subțierea tablei osoase de partea erupției anormale."}],"correct":["C"],"pages":[309],"source":"set-2"},{"id":"set2-kxV6f-7U","fingerprint":"ffa043faa0811084","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele sunt considerate iatrogenii ce pot afecta parodonțiul?","options":[{"id":"A","text":"Realizarea de obturații ocluzale care respectă contactele premature."},{"id":"B","text":"Instrumentarea endodontică agresivă."},{"id":"C","text":"Tratamentele ortodontice conduse neadecvat."},{"id":"D","text":"Realizarea de obturații de compozit nefinisate și rugoase."},{"id":"E","text":"Șlefuirea supragingivală, realizată cu o granulație fină a frezei."}],"correct":["B","C","D"],"pages":[310],"source":"set-2"},{"id":"set2-fC93x-hI","fingerprint":"92bc6c86c52419d6","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce consecințe pot avea coroanele protetice cu margini neadaptate asupra sănătății parodontale?","options":[{"id":"A","text":"Coroanele cu margini prea scurte stimulează atașamentul epitelial."},{"id":"B","text":"Coroanele prea înalte determină traumă ocluzală."},{"id":"C","text":"Coroanele cu margini prea lungi previn acumularea de placă bacteriană."},{"id":"D","text":"Coroanele cu margini prea lungi agresează spațiul biologic."},{"id":"E","text":"Coroanele cu margini prea scurte duc la retenția de placă bacteriană."}],"correct":["B","D","E"],"pages":[310],"source":"set-2"},{"id":"set2-JQ5R6Nlv","fingerprint":"6ad68c5938620acf","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este relația dintre bacteriile parodonto-patogene și răspunsul imun al gazdei în declanșarea bolii parodontale?","options":[{"id":"A","text":"Un răspuns imuno-inflamator eficient duce la distrucția țesuturilor parodontale."},{"id":"B","text":"Răspunsul imun este singurul factor necesar, prezența bacteriilor fiind secundară."},{"id":"C","text":"Bacteriile parodonto-patogene pot declanșa singure boala, indiferent de răspunsul imun."},{"id":"D","text":"Într-un organism cu susceptibilitate crescută, bacteriile nu au niciun impact clinic."},{"id":"E","text":"Ambele, prezența bacteriilor și un răspuns imun susceptibil, sunt necesare pentru declanșarea bolii."}],"correct":["E"],"pages":[310],"source":"set-2"},{"id":"set2-2lrzKxm6","fingerprint":"815a8e080144119d","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Cum influențează diferențele de susceptibilitate a organismului gazdă manifestările clinice și evoluția parodontitelor?","options":[{"id":"A","text":"Toate persoanele sunt vulnerabile în mod egal la efectele patogenilor parodontali."},{"id":"B","text":"Susceptibilitatea gazdei nu influențează riscul de recidivă după tratament."},{"id":"C","text":"Un organism cu susceptibilitate scăzută poate să nu prezinte un impact clinic în prezența patogenilor."},{"id":"D","text":"Pacienți cu patogeni bacterieni similari vor manifesta întotdeauna aceeași formă a bolii."},{"id":"E","text":"Răspunsul la tratamentul parodontal este uniform și nu depinde de capacitatea de vindecare a gazdei."}],"correct":["C"],"pages":[310],"source":"set-2"},{"id":"set2-mdeO0T4_","fingerprint":"9d6f755c483f8b6f","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afecțiuni sunt menționate ca factori sistemici predispozanți pentru apariția bolii parodontale?","options":[{"id":"A","text":"Stressul și sindroamele psiho-somatice."},{"id":"B","text":"Bolile endocrine."},{"id":"C","text":"Hipertensiunea arterială."},{"id":"D","text":"Afecțiunile renale cronice."},{"id":"E","text":"Deficiențele imune."}],"correct":["A","B","E"],"pages":[310],"source":"set-2"},{"id":"set2-NG99xT8Q","fingerprint":"4edebf898b567696","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt efectele fumatului și ale unui control metabolic slab al diabetului asupra statusului parodontal?","options":[{"id":"A","text":"Îmbunătățesc igiena orală prin conștientizarea riscurilor asociate."},{"id":"B","text":"Determină modificări ale desfășurării și caracteristicilor reacției imuno-inflamatorii."},{"id":"C","text":"Diminuează răspunsul inflamator local, prevenind distrucția tisulară."},{"id":"D","text":"Reduc prevalența și severitatea bolii parodontale."},{"id":"E","text":"Modifică micro-arhitectura la nivel vascular parodontal."}],"correct":["B","E"],"pages":[311],"source":"set-2"},{"id":"set2-zJsIhTVL","fingerprint":"ac5165afe19c9388","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Conform clasificării utilizate de Diagrama de Apreciere a Riscului Parodontal, cum este definit un \"fumător moderat\"?","options":[{"id":"A","text":"O persoană care a renunțat la fumat de mai mult de 5 ani."},{"id":"B","text":"O persoană care fumează mai puțin de 10 țigări pe zi."},{"id":"C","text":"O persoană care fumează mai mult de 20 de țigări pe zi."},{"id":"D","text":"O persoană care fumează între 10 și 20 de țigări pe zi."},{"id":"E","text":"O persoană care fumează doar ocazional, la evenimente sociale."}],"correct":["D"],"pages":[311],"source":"set-2"},{"id":"set2-p37lUzEi","fingerprint":"db093e3aab14becb","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"În cadrul clasificării parodontitelor din 2018, ce rol specific îndeplinesc factorii de risc precum diabetul zaharat și fumatul?","options":[{"id":"A","text":"Sunt utilizați exclusiv pentru a calcula intervalul între vizitele la medic."},{"id":"B","text":"Sunt criterii esențiale pentru stabilirea stadiului bolii."},{"id":"C","text":"Indică prezența unei boli sistemice, dar nu influențează clasificarea parodontitei."},{"id":"D","text":"Sunt modificatori ai gradului parodontitei."},{"id":"E","text":"Definesc complexitatea managementului cazului."}],"correct":["D"],"pages":[311],"source":"set-2"},{"id":"set2-yvOEbtMn","fingerprint":"121f056ff5bc6fe2","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt pragurile specifice pentru diabet și fumat care acționează ca modificatori ai gradului în clasificarea parodontitelor din 2018?","options":[{"id":"A","text":"Consumul a minimum 10 țigări zilnic."},{"id":"B","text":"Consumul a peste 20 de țigări zilnic."},{"id":"C","text":"Valoarea hemoglobinei glicozilate mai mare de 9%."},{"id":"D","text":"Valoarea hemoglobinei glicozilate de 7%."},{"id":"E","text":"Orice nivel de consum de tutun."}],"correct":["A","D"],"pages":[311],"source":"set-2"},{"id":"set2-r7TJuAD8","fingerprint":"3e6d1ab433e8e384","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce informații sunt corecte referitor la riscul de parodontită la pacienții cu diabet?","options":[{"id":"A","text":"Riscul de parodontită este crescut de două până la trei ori la persoanele cu diabet comparativ cu cele fără această boală."},{"id":"B","text":"Adulții cu vârsta peste 45 de ani și diabet slab controlat (hemoglobină glicozilată &gt;9%) au un risc de 2,9 ori mai mare de a dezvolta parodontită severă."},{"id":"C","text":"Nivelul de control glicemic este un factor secundar în determinarea riscului."},{"id":"D","text":"Riscul crescut de infecții este cauzat de o activitate exacerbată a monocitelor și macrofagelor."},{"id":"E","text":"Bolile parodontale sunt considerate \"a șasea complicație a diabetului\"."}],"correct":["A","B","E"],"pages":[311],"source":"set-2"},{"id":"set2-334SfEdG","fingerprint":"7f51e7024d1010cf","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care funcții celulare defensive sunt afectate la pacienții cu diabet slab controlat, diminuând apărarea primară împotriva patogenilor parodontali?","options":[{"id":"A","text":"Producția de limfocite B în măduva osoasă."},{"id":"B","text":"Funcțiile monocitelor și macrofagelor."},{"id":"C","text":"Chemotactismul și aderența PMN."},{"id":"D","text":"Activitatea celulelor Natural Killer (NK)."},{"id":"E","text":"Fagocitoza."}],"correct":["B","C","E"],"pages":[311],"source":"set-2"},{"id":"set2-c1HwPR5_","fingerprint":"746d261aa001808b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect relația dintre diabet și boala parodontală?","options":[{"id":"A","text":"Diabetul reduce prevalența bolii parodontale, dar crește severitatea acesteia."},{"id":"B","text":"Asociația Americană de Diabet recomandă medicilor stomatologi să trimită pacienții la specialistul diabetolog."},{"id":"C","text":"Bolile parodontale sunt considerate \"a șasea complicație a diabetului\"."},{"id":"D","text":"Prevalența și severitatea parodontitelor sunt crescute la pacienții cu diabet."},{"id":"E","text":"Controlul slab al nivelului glicemiei nu influențează gradul de severitate al parodontitelor."}],"correct":["C","D"],"pages":[312],"source":"set-2"},{"id":"set2-yVx7bWF1","fingerprint":"6fcc9d21a3a633a0","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce recomandări specifice sunt incluse în Standardele de Îngrijire ale Asociației Americane de Diabet privind sănătatea orală?","options":[{"id":"A","text":"Pacienților cu diabet le este recomandat să evite tratamentele stomatologice complexe."},{"id":"B","text":"Specialiștii diabetologici sunt îndrumați să trimită pacienții la medicul stomatolog pentru o evaluare cuprinzătoare."},{"id":"C","text":"Medicii stomatologi trebuie să monitorizeze nivelul glicemiei pacienților diabetici."},{"id":"D","text":"Includerea unui istoric al controlului glicemic în fișa stomatologică a pacientului."},{"id":"E","text":"Realizarea exclusiv a tratamentelor de urgență la pacienții cu diabet necontrolat."}],"correct":["B"],"pages":[312],"source":"set-2"},{"id":"set2-uI32b_u4","fingerprint":"1712a4277f8fc937","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt consecințele fumatului asupra bolii parodontale și a managementului acesteia?","options":[{"id":"A","text":"Recomandarea de a renunța la fumat este considerată o componentă a terapiei parodontale."},{"id":"B","text":"Fumatul crește eficacitatea tratamentului parodontal."},{"id":"C","text":"Fumatul nu influențează rezultatele tratamentului la pacienții care continuă acest obicei."},{"id":"D","text":"La fumători, se observă o scădere a prevalenței și severității parodontitei."},{"id":"E","text":"Fumatul este un factor de risc major pentru boala parodontală."}],"correct":["A","E"],"pages":[312],"source":"set-2"},{"id":"set2-7lsKe6Mw","fingerprint":"55aa20938facc557","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Conform datelor unui studiu din 2018 privind consumul de tutun la adulți în România, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Grupa de vârstă ≥65 de ani a înregistrat cea mai mare rată de consiliere pentru renunțarea la fumat din partea cadrelor medicale."},{"id":"B","text":"Medicii au sfătuit peste 80% dintre fumătorii care i-au vizitat să renunțe la fumat."},{"id":"C","text":"Proporția celor sfătuiți de un cadru medical să renunțe la fumat a fost minimă pentru grupa de vârstă 15–24 ani."},{"id":"D","text":"Mai puțin de 20% dintre adulții cu vârsta de minimum 15 ani erau consumatori de tutun."},{"id":"E","text":"Fumătorii consumă în medie 16,5 țigări pe zi."}],"correct":["A","C","E"],"pages":[312],"source":"set-2"},{"id":"set2-_zyNymyG","fingerprint":"30b3d2c7c0a92e18","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt unele dintre efectele sistemice pe termen lung ale fumatului?","options":[{"id":"A","text":"Producerea unui nivel înalt de stres oxidativ."},{"id":"B","text":"Scăderea nivelului proteinelor de fază acută, cum ar fi proteina C-reactivă și fibrinogenul."},{"id":"C","text":"Creșterea nivelului de antioxidanți, precum vitamina A și vitamina C."},{"id":"D","text":"Scăderea numărului total de leucocite, în special a celulelor polimorfonucleare."},{"id":"E","text":"Creșterea sintezei de citokine proinflamatorii precum IL-6 și TNF-α."}],"correct":["A","E"],"pages":[312],"source":"set-2"},{"id":"set2-2ZLJ4e0I","fingerprint":"867b68c829b6bac9","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Cum este afectat răspunsul inflamator gingival la acumularea de placă bacteriană în cazul fumătorilor, comparativ cu nefumătorii?","options":[{"id":"A","text":"Fumătorii dezvoltă forme unice de inflamație, neîntâlnite la nefumători."},{"id":"B","text":"Răspunsul inflamator este absent complet la fumători."},{"id":"C","text":"Dezvoltarea inflamației este exacerbată și accelerată la fumători."},{"id":"D","text":"Răspunsul inflamator este identic la ambele grupuri."},{"id":"E","text":"Fumătorii prezintă o inflamație gingivală mai redusă."}],"correct":["E"],"pages":[312],"source":"set-2"},{"id":"set2-VOBQwmfN","fingerprint":"9ce23bcd0d15fe17","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect impactul fumatului asupra structurilor parodontale?","options":[{"id":"A","text":"Pierderea de atașament parodontal are o prevalență mai scăzută la fumători."},{"id":"B","text":"La fumători, profunzimea pungilor parodontale este de obicei mai mică decât la nefumători."},{"id":"C","text":"Deși inflamația gingivală este redusă, distrucția parodontală este mai severă la fumători."},{"id":"D","text":"Fumatul duce la o prevalență și severitate crescute ale pierderii de os alveolar."},{"id":"E","text":"Fumătorii adulți în vârstă au o probabilitate de aproximativ trei ori mai mare de a avea boală parodontală severă."}],"correct":["C","D","E"],"pages":[312],"source":"set-2"},{"id":"set2-HDIO9dJl","fingerprint":"5d47e3ee34ae5075","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce factor legat de fumat este considerat semnificativ în pierderea dinților, formarea de carii de suprafață radiculară și boala parodontală?","options":[{"id":"A","text":"Vârsta la care a început fumatul."},{"id":"B","text":"Pauzele dintre perioadele de fumat."},{"id":"C","text":"Numărul de ani de fumat."},{"id":"D","text":"Consumul de țigări cu filtru versus fără filtru."},{"id":"E","text":"Tipul de tutun utilizat (pipă, țigări, trabuc)."}],"correct":["C"],"pages":[312],"source":"set-2"},{"id":"set2-JSYwmeqp","fingerprint":"acaf2e8d1273f2ba","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect riscurile asociate fumatului în contextul sănătății parodontale?","options":[{"id":"A","text":"Numărul anilor de fumat este un factor semnificativ doar în pierderea dinților, fără a influența alte afecțiuni orale."},{"id":"B","text":"Adulții tineri cu vârste între 19 și 30 de ani care fumează au o probabilitate de 3,8 ori mai mare de a avea parodontită față de nefumători."},{"id":"C","text":"Tinerii care fumează mai mult de 10 țigări pe zi prezintă cel mai crescut risc de pierdere a dinților."},{"id":"D","text":"Adulții în vârstă care fumează au o probabilitate de aproape 3 ori mai mare de a avea boală parodontală severă."},{"id":"E","text":"Fumătorii au o probabilitate de 6 ori mai mare de a prezenta pierdere de atașament parodontal comparativ cu nefumătorii."}],"correct":["B","D","E"],"pages":[313],"source":"set-2"},{"id":"set2-F_XLlh0F","fingerprint":"bced4a76516e2918","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Referitor la utilizarea tutunului fără ardere, care este afirmația corectă?","options":[{"id":"A","text":"Singurele efecte parodontale sunt recesia și pierderea de atașament localizată în zona de contact cu produsul."},{"id":"B","text":"Contribuie la reducerea severității parodontitei agresive generalizate."},{"id":"C","text":"Este asociată cu un risc crescut de leucoplazie orală și carcinoame orale."},{"id":"D","text":"Provoacă o progresie generalizată a bolii parodontale, similară fumatului."},{"id":"E","text":"Nu are niciun efect documentat asupra țesuturilor parodontale."}],"correct":["C"],"pages":[313],"source":"set-2"},{"id":"set2-iU-fHheJ","fingerprint":"3799ce46a47860f9","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce mecanisme pot explica deteriorarea parodontală mai agresivă la fumători, cauzată de alterarea interacțiunilor gazdă-bacterii?","options":[{"id":"A","text":"O diminuare a virulenței bacteriilor patogene, compensată de un răspuns imun exacerbat."},{"id":"B","text":"O creștere a numărului și virulenței organismelor patogene din placa subgingivală."},{"id":"C","text":"O combinație între alterarea florei subgingivale și modificarea răspunsului gazdei."},{"id":"D","text":"O reducere a cantității de placă subgingivală, dar cu o compoziție mai patogenă."},{"id":"E","text":"Modificări ale răspunsului gazdei la agresiunea microbiană."}],"correct":["B","C","E"],"pages":[313],"source":"set-2"},{"id":"set2-LTuIDOHH","fingerprint":"74fda25f9971310a","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele caracteristici clinice și vasculare sunt specifice fumătorilor în comparație cu nefumătorii?","options":[{"id":"A","text":"Densitatea vasculară a gingiei sănătoase este semnificativ mai redusă."},{"id":"B","text":"Concentrația de oxigen din țesuturile gingivale sănătoase este mai ridicată."},{"id":"C","text":"Temperatura subgingivală înregistrează valori mai scăzute."},{"id":"D","text":"Sângerarea la sondare și numărul vaselor sanguine de la nivel gingival sunt mai reduse."},{"id":"E","text":"Revenirea de la vasoconstricția provocată de anestezice durează mai mult."}],"correct":["C","D","E"],"pages":[313],"source":"set-2"},{"id":"set2-MTUR257c","fingerprint":"e6c75ff0875564c8","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Cum influențează fumatul rezultatele terapiei parodontale?","options":[{"id":"A","text":"Datorită unui răspuns mai bun la tratament, fumătorii devin rareori refractari la terapia parodontală."},{"id":"B","text":"Fumătorii prezintă o reducere mai mică a adâncimii pungilor chiar și atunci când se utilizează terapie adjunctă cu antimicrobiene topice."},{"id":"C","text":"Efectele dăunătoare ale fumatului asupra rezultatelor terapeutice par să fie de lungă durată și independente de frecvența terapiei de menținere."},{"id":"D","text":"Câștigul de atașament clinic ca urmare a detartrajului și planării radiculare este mai mare la fumători."},{"id":"E","text":"Reducerea adâncimii pungilor parodontale prin terapie inițială (detartraj și planare radiculară) este mai puțin eficientă."}],"correct":["B","C","E"],"pages":[313],"source":"set-2"},{"id":"set2-PDXC_wYy","fingerprint":"b5ba11bd85393911","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile care descriu caracteristicile ritmului de formare a biofilmului dentar?","options":[{"id":"A","text":"Formarea este mai accelerată pe fețele proximale față de cele vestibulare sau orale."},{"id":"B","text":"Ritmul de depunere este cu 50% mai mare în timpul zilei față de perioada nocturnă."},{"id":"C","text":"Rata de formare scade odată cu înaintarea în vârstă."},{"id":"D","text":"Formarea este mai rapidă la nivelul maxilarului comparativ cu mandibula."},{"id":"E","text":"Depunerea este mai rapidă în apropierea zonelor de inflamație gingivală comparativ cu zonele neinflamate."}],"correct":["A","B","E"],"pages":[299],"source":"set-2"},{"id":"set2-PE5j7AF-","fingerprint":"66361f630fbac80b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele elemente intră în compoziția matricei extracelulare a biofilmului dentar?","options":[{"id":"A","text":"Lipide rezultate din liza bacteriilor moarte."},{"id":"B","text":"Imunoglobuline de origine salivară."},{"id":"C","text":"Componente anorganice reprezentate exclusiv de ioni de sodiu și clor."},{"id":"D","text":"Proteine provenite în special din liza glicoproteinelor salivare sub acțiunea bacteriilor."},{"id":"E","text":"Polizaharide de origine predominant salivară, precum mutanul și levanul."}],"correct":["A","B","D"],"pages":[299],"source":"set-2"},{"id":"set2-Legm9FAE","fingerprint":"e985d1d58e41de84","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt interacțiunile de natură metabolică și de inhibiție stabilite între speciile bacteriene ale biofilmului dentar?","options":[{"id":"A","text":"Treponema denticola produce acid succinic, iar Campylobacter rectus produce protohem, ambii produși fiind utilizați în metabolismul Porphyromonas gingivalis."},{"id":"B","text":"Porphyromonas gingivalis furnizează acid izobutiric, substanță care stimulează creșterea Treponema denticola."},{"id":"C","text":"Aggregatibacter actinomycetemcomitans secretă actinobacilină, care stimulează dezvoltarea Streptococcus mutans."},{"id":"D","text":"Speciile de streptococi produc peroxid de hidrogen cu efect inhibitor asupra creșterii Aggregatibacter actinomycetemcomitans."},{"id":"E","text":"Fusobacterium nucleatum favorizează dezvoltarea Porphyromonas gingivalis prin scăderea pH-ului local pe baza sintezei de acid aspartic."}],"correct":["A","B","D"],"pages":[300],"source":"set-2"},{"id":"set2-OqsDrICV","fingerprint":"8e1f99ddaa13bcba","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele implicate în creșterea marcantă a rezistenței la antibiotice a bacteriilor din cadrul biofilmului dentar?","options":[{"id":"A","text":"Absența totală a schimburilor de informație genetică între microorganismele comunității."},{"id":"B","text":"Scăderea difuziunii substanței antibiotice prin structura matricei extracelulare a plăcii."},{"id":"C","text":"Eliminarea antibioticului în exteriorul celulei de către populații bacteriene „super-rezistente”, proces mediat de pompele de eflux."},{"id":"D","text":"Accelerarea ratei de creștere bacteriană, însoțită de diviziuni celulare frecvente."},{"id":"E","text":"Producția de către bacterii a unor enzime specifice, precum β-lactamaza și formaldehid-dehidrogenaza, care degradează antibioticele."}],"correct":["B","C","E"],"pages":[301],"source":"set-2"},{"id":"set2-TtAU1pgT","fingerprint":"616d8cabbe3d5689","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre afirmațiile referitoare la complexele bacteriene ale biofilmului subgingival reflectă organizarea patogenică a acestora?","options":[{"id":"A","text":"Complexele violet, verde și galben sunt principalii determinanți ai inflamației în boala parodontală avansată."},{"id":"B","text":"Colonizarea zonelor subgingivale de către bacteriile complexului roșu precede instalarea speciilor din complexul portocaliu."},{"id":"C","text":"Complexul roșu este alcătuit din Tannerella forsythia, Porphyromonas gingivalis și Treponema denticola, fiind asociat cu pungile profunde și pierderea de atașament."},{"id":"D","text":"Aggregatibacter actinomycetemcomitans serotipul b este integrat funcțional în complexul verde."},{"id":"E","text":"Complexul portocaliu include specii precum Fusobacterium spp., Prevotella intermedia și Parvimonas micra."}],"correct":["C","E"],"pages":[301],"source":"set-2"},{"id":"set2-7YSu-s25","fingerprint":"eeb166e24d8647ab","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile microbiologice ale Aggregatibacter actinomycetemcomitans?","options":[{"id":"A","text":"Prezintă o motilitate intensă prin prezența flagelilor."},{"id":"B","text":"Este un cocobacil Gram-pozitiv."},{"id":"C","text":"Este un microorganism cu metabolism facultativ anaerob."},{"id":"D","text":"Funcționează pe baza unui metabolism de tip asaharolitic."},{"id":"E","text":"Necesită dioxid de carbon pentru creștere, având un metabolism capnofil."}],"correct":["C","E"],"pages":[301],"source":"set-2"},{"id":"set2-IflpdBi6","fingerprint":"262a45ba425c349e","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care aspecte clinice și topografice justifică asocierea majoră a bacteriei Aggregatibacter actinomycetemcomitans cu boala parodontală?","options":[{"id":"A","text":"Microorganismul predomină în pungile parodontale superficiale în detrimentul celor profunde."},{"id":"B","text":"Detecția se realizează mai frecvent în defectele infraosoase comparativ cu defectele supraosoase."},{"id":"C","text":"Nivelul bacterian în placa subgingivală crește semnificativ cu aproximativ un an înainte de apariția semnelor clinice."},{"id":"D","text":"Majoritatea subiecților afectați de parodontită agresivă localizată dezvoltă un titru crescut de anticorpi față de acest patogen."},{"id":"E","text":"Bacteria este depistată cu precădere în leziunile inactive, rolul ei fiind preponderent static."}],"correct":["B","C","D"],"pages":[301],"source":"set-2"},{"id":"set2-k7oH0cye","fingerprint":"e969446ca37dfe44","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile valabile referitoare la factorii de virulență asociați cu Aggregatibacter actinomycetemcomitans?","options":[{"id":"A","text":"Capacitatea de a invada țesutul gingival are implicații majore în orientarea spre terapii adjuvante de eradicare."},{"id":"B","text":"Majoritatea șușelor produc o cantitate masivă de leucotoxină, utilă ca indicator diagnostic direct."},{"id":"C","text":"Clona JP2 a bacteriei secretă o cantitate de leucotoxină de 10-20 de ori mai mare decât restul clonelor."},{"id":"D","text":"Virulența este potențată prin sinteza colagenazelor și prin prezența lipopolizaharidelor de suprafață."},{"id":"E","text":"Leucotoxina limitează infecția prin distrugerea exclusivă a celulelor epiteliale din șanțul gingival."}],"correct":["A","C","D"],"pages":[301],"source":"set-2"},{"id":"set2-SWGa9cdu","fingerprint":"2aa959aafc920001","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este pragul numeric de celule microbiene asociat agenților patogeni Aggregatibacter actinomycetemcomitans și Porphyromonas gingivalis necesar pentru a se corela cu pierderea viitoare de atașament parodontal?","options":[{"id":"A","text":"10⁸ celule microbiene"},{"id":"B","text":"10⁶ celule microbiene"},{"id":"C","text":"10⁵ celule microbiene"},{"id":"D","text":"10³ celule microbiene"},{"id":"E","text":"10⁴ celule microbiene"}],"correct":["B"],"pages":[301],"source":"set-2"},{"id":"set2-NkqX2WAS","fingerprint":"3cb1575c6c895168","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce aspecte caracterizează interacțiunea patogenică dintre Aggregatibacter actinomycetemcomitans și parodontita agresivă localizată?","options":[{"id":"A","text":"Identificarea unui număr redus de celule microbiene garantează declanșarea automată a distrucției parodontale pe termen scurt."},{"id":"B","text":"Pacienții care sunt simpli purtători ai bacteriei prezintă un risc identic de a dezvolta boala cu pacienții nepurtători."},{"id":"C","text":"Absența eradicării bacteriei din mediul subgingival se corelează frecvent cu un eșec terapeutic."},{"id":"D","text":"Dezvoltarea afecțiunii este cauzată strict de prezența unei monoinfecții cu acest patogen."},{"id":"E","text":"Abordările clinice capabile să asigure eradicarea subgingivală a patogenului generează îmbunătățiri clinice marcate."}],"correct":["C","E"],"pages":[301],"source":"set-2"},{"id":"set2-LIWQaOut","fingerprint":"474d5e11fea5d910","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile descriptive și ecologice ale bacteriei Porphyromonas gingivalis?","options":[{"id":"A","text":"Poate fi detectat în parodontitele cu evoluție rapidă și în leziunile din parodontita agresivă localizată."},{"id":"B","text":"Prezența sa subgingivală se asociază exclusiv cu starea de boală parodontală severă."},{"id":"C","text":"Reprezintă o specie dominantă ca număr și prevalență în majoritatea leziunilor de parodontită cronică."},{"id":"D","text":"Este un coco-bacil Gram-negativ, strict anaerob."},{"id":"E","text":"Se dezvoltă exclusiv în prezența oxigenului, formând colonii maro închis-negre."}],"correct":["A","C","D"],"pages":[302],"source":"set-2"},{"id":"set2-2RiyuCUp","fingerprint":"9af028e97f6a42d8","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele elemente reprezintă factori de virulență ai bacteriei Porphyromonas gingivalis?","options":[{"id":"A","text":"Produșii de metabolism toxici"},{"id":"B","text":"Un echipament enzimatic complex destinat stimulării directe a imunității înnăscute"},{"id":"C","text":"Lipopolizaharidul de suprafață"},{"id":"D","text":"O capsulă ce favorizează implicarea în distrucția parodontală"},{"id":"E","text":"Gingipainele, reprezentând un arsenal proteolitic important"}],"correct":["A","C","D","E"],"pages":[302],"source":"set-2"},{"id":"set2-UhuIjQXr","fingerprint":"261eacc5aa4f3aca","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Prin ce mecanisme patogenice acționează Porphyromonas gingivalis ca patogen cheie în dezvoltarea bolii parodontale?","options":[{"id":"A","text":"Acționează prin potențarea și stimularea imunității înnăscute de la nivelul parodonțiului."},{"id":"B","text":"Distruge relațiile homeostatice normale dintre flora microbiană și parodonțiu."},{"id":"C","text":"Modifică proporția bacteriilor din structura biofilmului."},{"id":"D","text":"Permite stabilirea unei comunități microbiene disbiotice responsabile de o inflamație intensă."},{"id":"E","text":"Inhibă specific flora microbiană asociată cu statusul de boală pentru a stopa distrucția tisulară."}],"correct":["B","C","D"],"pages":[302],"source":"set-2"},{"id":"set2-ipvi-LJB","fingerprint":"edcd1487b8c29e08","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce implicație clinică majoră derivă din capacitatea bacteriei Porphyromonas gingivalis de a susține și stabiliza flora microbiană asociată statusului de boală?","options":[{"id":"A","text":"Eliminarea sa din biofilmul subgingival poate reprezenta una dintre țintele terapiei parodontale."},{"id":"B","text":"Neutralizarea izolată a produșilor de metabolism toxici garantează menținerea sănătății parodontale chiar și în prezența biofilmului."},{"id":"C","text":"Se impune îndepărtarea exclusivă a florei microbiene aerobe din pungile parodontale."},{"id":"D","text":"Terapia trebuie să vizeze creșterea artificială a imunității înnăscute pentru stimularea producerii de gingipaine."},{"id":"E","text":"Administrarea profilactică de antibiotice imunosupresoare neutralizează direct declanșarea disbiozei la pacienții sănătoși."}],"correct":["A"],"pages":[302],"source":"set-2"},{"id":"set2-rxJB5xAE","fingerprint":"8f888f019b161093","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt efectele acidului butiric la nivelul structurilor parodontale?","options":[{"id":"A","text":"Lărgirea spațiilor intercelulare ale epiteliului gingival"},{"id":"B","text":"Apoptoza fibroblastelor"},{"id":"C","text":"Degradarea fibronectinei și a elastinei"},{"id":"D","text":"Inducerea apoptozei limfocitelor B și T"},{"id":"E","text":"Apoptoza celulelor epiteliale gingivale"}],"correct":["B","D","E"],"pages":[303],"source":"set-2"},{"id":"set2-iljMK2l6","fingerprint":"8895813b25610ef4","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care dintre următorii produși de metabolism este direct responsabil de lărgirea spațiilor intercelulare ale epiteliului și alterarea metabolismului fibroblastelor?","options":[{"id":"A","text":"Hidrogenul sulfurat"},{"id":"B","text":"Acidul butiric"},{"id":"C","text":"Metil-mercaptanul"},{"id":"D","text":"Acidul propionic"},{"id":"E","text":"Gingipainele"}],"correct":["C"],"pages":[302],"source":"set-2"},{"id":"set2-Fr4Phz5T","fingerprint":"1bf2256b0d6f59ab","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile valabile referitoare la gingipaine, ca factori de virulență ai Porphyromonas gingivalis?","options":[{"id":"A","text":"Degradează componente ale complementului, precum C3, C4, C5 și factorul B"},{"id":"B","text":"Cresc sinteza de interleukina-6 (IL-6) și IL-8 de către monocite"},{"id":"C","text":"Sunt lipopolizaharide care interacționează cu celulele dendritice"},{"id":"D","text":"Distrug factorul de necroză tumorală alfa (TNF-α)"},{"id":"E","text":"Formează o capsulă extracelulară cu rol de protecție"}],"correct":["A","B","D"],"pages":[303],"source":"set-2"},{"id":"set2-mSLV1ngb","fingerprint":"6bfbd7b9bf258f57","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele prin care bacteriile parodonto-patogene evită sistemul imun al organismului?","options":[{"id":"A","text":"Invazia celulelor epiteliale gingivale"},{"id":"B","text":"Activarea componentelor complementului prin intermediul fimbriilor"},{"id":"C","text":"Degradarea unor componente ale sistemului imun prin intermediul unui sistem proteolitic"},{"id":"D","text":"Formarea unei capsule polizaharidice extracelulare"},{"id":"E","text":"Sinteza de acid acetic și propionic"}],"correct":["A","C","D"],"pages":[303],"source":"set-2"},{"id":"set2-iuHbhjSk","fingerprint":"3f45f2e2ee2cface","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"În ce condiții se produce invazia țesutului conjunctiv gingival de către Porphyromonas gingivalis?","options":[{"id":"A","text":"Ca primă etapă a colonizării în prezența lipopolizaharidelor"},{"id":"B","text":"În stadiile mai avansate ale distrucției parodontale, consecutiv inflamației și distrucției tisulare"},{"id":"C","text":"Imediat după lărgirea spațiilor intercelulare de către acidul propionic"},{"id":"D","text":"În urma interacțiunii exclusive a lipopolizaharidelor cu limfocitele T"},{"id":"E","text":"Exclusiv prin stimularea imensă a secreției de IL-6 și IL-8 mediată de acidul butiric"}],"correct":["B"],"pages":[303],"source":"set-2"},{"id":"set2-QXDk0TyD","fingerprint":"37c851504a474717","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele modificări ale microbiotei subgingivale caracterizează tranziția de la starea de sănătate la parodontită?","options":[{"id":"A","text":"Tranziția de la specii fermentative la specii proteolitice."},{"id":"B","text":"Modificarea populației de la bacterii Gram-negative la bacterii Gram-pozitive."},{"id":"C","text":"Trecerea de la specii motile la bacterii non-motile."},{"id":"D","text":"Tranziția de la bacterii facultativ anaerobe la bacterii strict anaerobe."},{"id":"E","text":"Schimbarea morfologiei dominante de la coci la bacili."}],"correct":["A","D","E"],"pages":[304],"source":"set-2"},{"id":"set2-eB8cjbh-","fingerprint":"5993223d1a6607f1","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt factorii care pot determina perturbarea răspunsului imun al organismului la nivelul parodonțiului, favorizând instalarea disbiozei?","options":[{"id":"A","text":"Modificările echilibrului hormonal apărute în timpul sarcinii."},{"id":"B","text":"Acumularea excesivă de placă subgingivală."},{"id":"C","text":"Declanșarea unor afecțiuni autoimune."},{"id":"D","text":"Factori de mediu, precum fumatul și regimul alimentar."},{"id":"E","text":"Scăderea fluxului crevicular asociată inflamației locale."}],"correct":["A","B","C","D"],"pages":[304],"source":"set-2"},{"id":"set2-RjtiWXOu","fingerprint":"80e9b3e2f952d187","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este obiectivul terapeutic principal în managementul clinic al disbiozei parodontale?","options":[{"id":"A","text":"Diminuarea mecanică a fluxului crevicular pentru a reduce inflamația locală."},{"id":"B","text":"Reducerea sau eliminarea stimulului care a condus la apariția disbiozei."},{"id":"C","text":"Țintirea terapeutică directă a unor specii bacteriene parodonto-patogene specifice."},{"id":"D","text":"Eradicarea exclusivă a bacteriilor strict anaerobe din punga parodontală."},{"id":"E","text":"Inducerea unei tranziții microbiene către un profil format dominant din bacili și specii motile."}],"correct":["B"],"pages":[304],"source":"set-2"},{"id":"set2-wizIorzK","fingerprint":"179b32c79aa0d8cc","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile transmisiei și translocării bacteriilor parodonto-patogene?","options":[{"id":"A","text":"Transmiterea interumană a bacteriilor parodonto-patogene constituie o problemă în termeni epidemiologici."},{"id":"B","text":"La pacienții parțial edentați, dinții restanți acționează ca rezervor bacterian pentru colonizarea implanturilor."},{"id":"C","text":"Translocarea mecanică a bacteriilor se produce exclusiv spre situsuri deja infectate."},{"id":"D","text":"Reușita translocării bacteriilor subgingivale este independentă de existența unor colonizatori prestabiliți în noul habitat."},{"id":"E","text":"Translocarea bacteriilor din zone subgingivale în regiuni periimplantare sterile se desfășoară într-un ritm rapid."}],"correct":["A","B","E"],"pages":[304],"source":"set-2"},{"id":"set2-0nDFXO4b","fingerprint":"4bbf5c7ac3f05e05","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este mecanismul principal prin care este prevenită degranularea intra-tisulară a neutrofilelor și sunt inițiate procesele de rezoluție a inflamației în condiții de homeostazie parodontală?","options":[{"id":"A","text":"Fagocitarea neutrofilelor apoptotice de către macrofagele tisulare"},{"id":"B","text":"Sinteza de resolvine endogene de către leucocitele polimorfonucleare"},{"id":"C","text":"Stimularea masivă a formării de citokine proinflamatorii în timpul apoptozei"},{"id":"D","text":"Hiperfuncționalitatea genetică a leucocitelor polimorfonucleare"},{"id":"E","text":"Eliberarea speciilor reactive de oxigen de către fibroblastele activate"}],"correct":["A"],"pages":[304],"source":"set-2"},{"id":"set2-scRauvz9","fingerprint":"9f289681b7644d89","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la mecanismele de producere a distrucției parodontale?","options":[{"id":"A","text":"Distrucția parodontală se produce majoritar prin mecanism direct, inițiat exclusiv de enzimele bacteriene litice."},{"id":"B","text":"Procesele patologice sunt mediate de un consorțiu polimicrobian mai degrabă decât de parodonto-patogeni individuali."},{"id":"C","text":"Apoptoza neutrofilelor este accelerată de lipopolizaharidele bacteriene, scăzând dramatic longevitatea acestora în țesuturi."},{"id":"D","text":"Excesul de bacterii parodonto-patogene declanșează un răspuns imuno-inflamator intens și necontrolat la indivizii susceptibili."},{"id":"E","text":"Celulele locale parodontale, precum osteoclastele, macrofagele și celulele endoteliale, devin participanți majori ai distrucției."}],"correct":["B","D","E"],"pages":[305],"source":"set-2"},{"id":"set2-C4CtCFU5","fingerprint":"9a06bbeaa30e481a","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile inflamației cronice parodontale instalate în urma stimulării bacteriene continue?","options":[{"id":"A","text":"Supra-producția de mediatori proinflamatori prin activare continuă, proces care întreține și amplifică inflamația."},{"id":"B","text":"Clearance-ul ineficient al neutrofilelor pe fondul unui număr excesiv de microorganisme subgingivale."},{"id":"C","text":"Dereglarea sau întârzierea apoptozei neutrofilelor, însoțită de degranularea lor intra-tisulară."},{"id":"D","text":"Suprimarea completă a sintezei de radicali liberi prin epuizarea celulară."},{"id":"E","text":"Eficientizarea fazei de rezoluție a inflamației prin acțiunea prelungită a lipoxinelor."}],"correct":["A","B","C"],"pages":[305],"source":"set-2"},{"id":"set2-DAptn7OD","fingerprint":"81c8f6881f33e949","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este efectul direct al pătrunderii unei cantități mari de lipopolizaharide (LPZ) în țesuturile parodontale asupra leucocitelor polimorfonucleare neutrofile?","options":[{"id":"A","text":"Inhibă sinteza de metaloproteinaze tisulare, limitând distrucția fibrelor de colagen"},{"id":"B","text":"Induce direct eliberarea de mediatori lipidici antiinflamatori de tipul resolvinelor"},{"id":"C","text":"Accelerează apoptoza celulară imediat după fagocitoză, prevenind eliberarea extracelulară a enzimelor litice"},{"id":"D","text":"Induce instalarea precoce și definitivă a fazei de rezoluție a inflamației"},{"id":"E","text":"Determină neutrofilele să devină hiperfuncționale, stimulând secreția de mediatori pro-inflamatori și formarea speciilor reactive de oxigen"}],"correct":["E"],"pages":[305],"source":"set-2"},{"id":"set2-pCRWp5Li","fingerprint":"ca3d81d62785a7ec","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care dintre următoarele molecule reprezintă mediatori lipidici endogeni, cu efect antiinflamator, a căror sinteză este indusă de fagocitarea neutrofilelor apoptotice de către macrofage?","options":[{"id":"A","text":"Lipoxinele"},{"id":"B","text":"Chemokinele"},{"id":"C","text":"Metaloproteinazele"},{"id":"D","text":"Citokinele"},{"id":"E","text":"Resolvinele"}],"correct":["A"],"pages":[304],"source":"set-2"},{"id":"set2-UwmnCkxt","fingerprint":"a63f2116b1e6b31e","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt efectele interleukinei-1β (IL-1β) în cadrul procesului inflamator parodontal?","options":[{"id":"A","text":"Stimulează macrofagele să sintetizeze IL-6."},{"id":"B","text":"Crește expresia moleculelor de adeziune ICAM la nivelul celulelor endoteliale."},{"id":"C","text":"Funcționează ca antagonist direct al prostaglandinei E₂ (PGE₂)."},{"id":"D","text":"Induce apoptoza fibroblastelor."},{"id":"E","text":"Stimulează diferențierea celulelor T helper."}],"correct":["A","B","E"],"pages":[306],"source":"set-2"},{"id":"set2-O-_ipPom","fingerprint":"d39acaecce824c87","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Prin ce mecanism administrarea adjuvantă îndelungată a antiinflamatoarelor nesteroidiene favorizează dezvoltarea inflamației cronice persistente în boala parodontală?","options":[{"id":"A","text":"Neutralizează inhibitorii tisulari ai metaloproteinazelor (TIMP), dezechilibrând balanța enzimatică."},{"id":"B","text":"Declanșează producția excesivă de metaloproteinază-1 prin stimularea directă a fibroblastelor gingivale."},{"id":"C","text":"Inhibă prostaglandina E₂, care la o concentrație prag semnalizează inițierea mecanismelor de rezoluție a inflamației."},{"id":"D","text":"Induce o eliberare masivă de citokine cu efect antiinflamator care blochează regenerarea colagenului."},{"id":"E","text":"Stimulează activitatea osteoclastelor provocând resorbția osului alveolar adiacent pungilor parodontale."}],"correct":["C"],"pages":[306],"source":"set-2"},{"id":"set2-U4JcCVrK","fingerprint":"560ff12b23b233d3","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt rolurile și caracteristicile metaloproteinazelor în patogenia bolii parodontale?","options":[{"id":"A","text":"Fibroblastele sintetizează metaloproteinaza-1, implicată în menținerea homeostaziei parodontale."},{"id":"B","text":"Degradarea colagenului de tip 1 este realizată cu o eficiență crescută de către metaloproteinaza-8 și metaloproteinaza-9."},{"id":"C","text":"Neutrofilele din țesuturile inflamate eliberează metaloproteinaza-8 și metaloproteinaza-9."},{"id":"D","text":"Activitatea metaloproteinazelor este stimulată ireversibil prin atașarea inhibitorilor tisulari (TIMP)."},{"id":"E","text":"Metaloproteinazele inhibă recrutarea și activitatea osteoclastelor de la nivelul osului alveolar."}],"correct":["A","B","C"],"pages":[306],"source":"set-2"},{"id":"set2-95t0czft","fingerprint":"80768e0764e3b7ea","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este distanța critică sau condiția spațială esențială referitoare la țesuturile limitrofe în procesul de distrucție a osului alveolar?","options":[{"id":"A","text":"Resorbția osoasă se oprește doar atunci când distanța dintre os și epiteliul joncțional depășește 5 mm."},{"id":"B","text":"Distrugerea osoasă începe după ce țesutul conjunctiv a fost complet înlocuit de un infiltrat inflamator extins."},{"id":"C","text":"Resorbția osoasă osteoclastică se oprește la o înălțime maximă de 0,5 mm față de depozitul bacterian subgingival."},{"id":"D","text":"Osul se resoarbe astfel încât deasupra lui trebuie să persiste o înălțime minimă de 0,5-1 mm de țesut conjunctiv neinflamat."},{"id":"E","text":"Osul alveolar se resoarbe continuu până la dispariția totală a ligamentelor parodontale, indiferent de grosimea țesutului conjunctiv."}],"correct":["D"],"pages":[307],"source":"set-2"},{"id":"set2-jnEXnSzJ","fingerprint":"8a5b3b4c0e8210ef","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele elemente descriu corect mecanismele implicate în primele faze ale formării pungilor parodontale adevărate?","options":[{"id":"A","text":"Detașarea celulelor din zona cea mai coronară a epiteliului joncțional."},{"id":"B","text":"Îngroșarea colagenului subepitelial datorită activității enzimatice a neutrofilelor."},{"id":"C","text":"Migrarea apicală a celor mai apicale celule ale epiteliului joncțional în zona de distrugere a fibrelor de colagen."},{"id":"D","text":"Subțierea, ulcerarea și sângerarea ușoară a epiteliului pungii și a celui de atașament."},{"id":"E","text":"Migrarea coronară a epiteliului joncțional pentru a acoperi defectul țesutului conjunctiv."}],"correct":["A","C","D"],"pages":[307],"source":"set-2"},{"id":"set2-TiDjGcXc","fingerprint":"e7c77dee6bc33b78","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce roluri îndeplinește sistemul RANKL-osteoprotegerină în procesul de resorbție a osului alveolar?","options":[{"id":"A","text":"Osteoprotegerina previne atașamentul RANKL de receptorul progenitorilor osteoclastici."},{"id":"B","text":"Sistemul RANKL are rolul principal de a stimula sinteza colagenului tip 1 de către fibroblaste."},{"id":"C","text":"Receptorul RANK este situat exclusiv pe suprafața celulelor epiteliale ale pungii parodontale."},{"id":"D","text":"RANKL se leagă de receptorul RANK și stimulează diferențierea și activarea osteoclastică."},{"id":"E","text":"Citokinele proinflamatorii inhibă expresia RANKL pentru a opri resorbția osului alveolar."}],"correct":["A","D"],"pages":[307],"source":"set-2"},{"id":"set2-yiEGz3hg","fingerprint":"783ecc62988bde50","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele elemente sunt clasificate drept factori predispozanți locali implicați în etiopatogenia bolii parodontale?","options":[{"id":"A","text":"Trauma ocluzală"},{"id":"B","text":"Efectele radioterapiei"},{"id":"C","text":"Obiceiurile vicioase"},{"id":"D","text":"Biofilmul parodontal"},{"id":"E","text":"Tartrul"}],"correct":["A","B","C","E"],"pages":[307],"source":"set-2"},{"id":"set2-83KJCQMj","fingerprint":"1f0c1165632d63d2","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Prin ce iatrogenii sau particularități retentive acționează factorii predispozanți locali pentru a favoriza acumularea plăcii bacteriene?","options":[{"id":"A","text":"Marginile lucrărilor protetice inserate profund în șanțul gingival"},{"id":"B","text":"Croșetele neadaptate ale protezelor mobilizabile"},{"id":"C","text":"Aparatele ortodontice"},{"id":"D","text":"Materialele de obturație sau de placare protetică poroase"},{"id":"E","text":"Lucrările protetice cu margini situate la distanță de marginea gingivală"}],"correct":["C","D","E"],"pages":[307],"source":"set-2"},{"id":"set2-Fmq0e0QT","fingerprint":"610cade503123de5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt mecanismele patogenice prin care factorii predispozanți locali influențează direct țesuturile parodontale?","options":[{"id":"A","text":"Agresarea inserției epiteliale ca urmare a nerespectării spațiului biologic"},{"id":"B","text":"Dezvoltarea de forțe necorespunzătoare ca amplitudine și direcție din cauza unui tratament ortodontic condus neadecvat"},{"id":"C","text":"Crearea unor condiții anatomice caracterizate printr-un parodonțiu gros și septuri interdentare late"},{"id":"D","text":"Generarea de microtraume repetate asupra dinților în cazul prezenței unor migrări dentare"},{"id":"E","text":"Transformarea directă a tartrului în factor etiologic principal al bolii parodontale"}],"correct":["A","B","D"],"pages":[308],"source":"set-2"},{"id":"set2-OD_wB3fb","fingerprint":"b538b4936c69d577","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Ce mecanism lezional primar este declanșat la nivel dento-parodontal de către croșetele neadaptate ale protezelor mobilizabile și de lucrările protetice înalte?","options":[{"id":"A","text":"Producerea de microtraume repetate asupra dinților"},{"id":"B","text":"Crearea unor zone retentive de volum crescut pentru placa bacteriană"},{"id":"C","text":"Activarea directă a factorilor predispozanți sistemici"},{"id":"D","text":"Dezvoltarea unor septuri interdentare fine și vulnerabile"},{"id":"E","text":"Agresarea directă a inserției epiteliale prin invadarea spațiului biologic"}],"correct":["A"],"pages":[308],"source":"set-2"},{"id":"set2-63GqFkvj","fingerprint":"e3c71b88a343dc42","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele condiții clinice determină microtraume repetate asupra dinților, favorizând evoluția bolii parodontale?","options":[{"id":"A","text":"Migrările dentare"},{"id":"B","text":"Obturațiile neadaptate în vecinătatea marginii gingivale"},{"id":"C","text":"Obturațiile înalte"},{"id":"D","text":"Obiceiurile vicioase"},{"id":"E","text":"Lucrările protetice cu margini la distanță de marginea gingivală"}],"correct":["A","C","D"],"pages":[307],"source":"set-2"},{"id":"set2-WseiK2Ya","fingerprint":"75fd20887f1588b8","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt afirmațiile adevărate privind dinamica și ratele de formare a tartrului dentar?","options":[{"id":"A","text":"Procesul de depunere a tartrului continuă indefinit cu aceeași rată, în absența intervenției terapeutice."},{"id":"B","text":"Primele nuclee de calcificare ale matricei interbacteriene apar la 4-8 ore de la depunerea plăcii."},{"id":"C","text":"Creșterea medie a depozitelor de tartru se realizează cu o rată de 1,0-1,5%/zi față de cantitatea existentă."},{"id":"D","text":"Nivelul maxim de depunere a tartrului este atins într-un interval cuprins între 10 săptămâni și 6 luni."},{"id":"E","text":"Gradul de calcificare a plăcii bacteriene poate atinge un nivel de 60-90% în primele 48 de ore."}],"correct":["B","D"],"pages":[308,309],"source":"set-2"},{"id":"set2-DOfZYbmv","fingerprint":"0e3362ea74d5eb3e","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele aspecte descriu diferențele biochimice și de formare între tartrul supragingival și cel subgingival?","options":[{"id":"A","text":"Tartrul subgingival prezintă o concentrație mai crescută de sodiu și calciu în structura sa anorganică."},{"id":"B","text":"Hidroxiapatita lipsește cu desăvârșire din arhitectura cristalină a tartrului subgingival."},{"id":"C","text":"Proteinele salivare reprezintă constituenți specifici exclusiv depozitelor de tartru supragingival."},{"id":"D","text":"Componenta proteică salivară este distribuită uniform în ambele variante topografice de tartru."},{"id":"E","text":"Formarea tartrului subgingival are la origine elemente provenite din fluidul plasmatic."}],"correct":["A","C","E"],"pages":[308,309],"source":"set-2"},{"id":"set2-jF3Efjkf","fingerprint":"32259835d63ddb9d","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Prin ce mecanisme își exercită tartrul dentar acțiunea patogenă asupra țesuturilor parodontale?","options":[{"id":"A","text":"Provoacă o ischemie severă a țesutului conjunctiv prin comprimarea directă a rețelei vasculare parodontale."},{"id":"B","text":"Restricționează accesul fluidelor cu rol dezinfectant la nivelul suprafețelor dentare și în șanțul gingival."},{"id":"C","text":"Imobilizează placa bacteriană într-o poziție de contact permanent și strâns cu țesuturile gingivale învecinate."},{"id":"D","text":"Induce un efect litic direct prin secreția de enzime proteolitice la nivelul epiteliului joncțional."},{"id":"E","text":"Asigură locusuri propice pentru colonizarea microbiană, acționând ca un fundament pentru biofilmul parodontal."}],"correct":["B","C","E"],"pages":[308,309],"source":"set-2"},{"id":"set2-xYIZ8v8p","fingerprint":"95e5172fd0d8eb30","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt particularitățile structurale și compoziționale ce definesc „materia alba”?","options":[{"id":"A","text":"Consistența sa este redusă, având aspectul unui depozit moale de culoare alb-gri."},{"id":"B","text":"Structura depozitului include celule epiteliale descuamate, leucocite și microorganisme."},{"id":"C","text":"Dispune de o organizare arhitecturală internă similară cu cea a plăcii bacteriene mature."},{"id":"D","text":"Matricea sa anorganică este alcătuită preponderent din hidroxiapatită și cristale de brușită."},{"id":"E","text":"Componentele organice încorporează proteine și lipide derivate din mediul salivar."}],"correct":["A","B","E"],"pages":[308,309],"source":"set-2"},{"id":"set2-Ai3V3E0u","fingerprint":"6dcb6f9186ffc12c","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"În ceea ce privește localizarea topografică și caracteristicile clinice ale depozitelor de tartru, care afirmație este corectă?","options":[{"id":"A","text":"Depunerea masivă a tartrului este favorizată pe suprafețele vestibulare ale grupului incisiv inferior."},{"id":"B","text":"Varianta subgingivală de tartru este caracterizată printr-un nivel superior de duritate și aderență la substrat comparativ cu cea supragingivală."},{"id":"C","text":"Expunerea vizuală a tartrului supragingival necesită în prealabil instalarea unui proces de retracție gingivală."},{"id":"D","text":"Apropierea de orificiile canalelor excretoare ale glandelor salivare mari funcționează ca un factor frenator în procesul de mineralizare."},{"id":"E","text":"Îndepărtarea tartrului supragingival nemineralizat complet poate fi realizată cu succes prin periajul casnic."}],"correct":["B"],"pages":[308,309],"source":"set-2"},{"id":"set2-DUzWG_zv","fingerprint":"a34e1e8dc7dc7e99","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații sunt adevărate privind impactul anomaliilor dento-maxilare asupra parodonțiului?","options":[{"id":"A","text":"Incongruența dento-alveolară cu spațiere este însoțită de fenomene de hipertrofie a papilelor interdentare."},{"id":"B","text":"Ocluzia deschisă favorizează inflamația gingivală prin accentuarea virulenței plăcii bacteriene deshidratate."},{"id":"C","text":"Prognațiile mandibulare pot conduce la vestibulo-versii importante ale incisivilor mandibulari, cu inducerea unui parodonțiu fin."},{"id":"D","text":"Compresiunea de maxilar se poate însoți de demineralizări ale septurilor interdentare în zonele laterale."},{"id":"E","text":"În cazul ectopiilor, se conturează o îngroșare a fibromucoasei de partea erupției ectopice și un parodonțiu fin de partea opusă."}],"correct":["B","C","D"],"pages":[309],"source":"set-2"},{"id":"set2-imh6nuOX","fingerprint":"f4a252b8da464f57","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este consecința aplicării unor coroane protetice cu margini prea scurte asupra țesuturilor parodontale?","options":[{"id":"A","text":"Agresarea directă a spațiului biologic."},{"id":"B","text":"Apariția de fenestrații și dehiscente în timpul erupției."},{"id":"C","text":"Retenția de placă bacteriană."},{"id":"D","text":"Crearea unor interferențe și contacte premature."},{"id":"E","text":"Generarea unei traume ocluzale."}],"correct":["C"],"pages":[310],"source":"set-2"},{"id":"set2-WrqClT1F","fingerprint":"4a0f37c617c33464","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt caracteristicile distrofiilor dentare și ale prezenței dinților supranumerari în raport cu afectarea parodontală?","options":[{"id":"A","text":"Dinții supranumerari duc la conformarea unui parodonțiu fin, cu deficit de troficitate, susceptibil la atacul bacterian."},{"id":"B","text":"Distrofiile dentare favorizează depunerea de placă bacteriană prin suprafața lor rugoasă, cu margini neregulate și anfractuoase."},{"id":"C","text":"Distrofiile dentare determină atrofia papilelor interdentare prin impact alimentar direct, independent de placa bacteriană."},{"id":"D","text":"Dinții supranumerari duc la conformarea unui parodonțiu gros și hipertrofic, rezistent la atacul bacterian."},{"id":"E","text":"În cazul distrofiilor dentare, inflamația parodontală poate să apară mai ales când leziunile se învecinează cu marginea gingivală, în condițiile unui deficit de igienă."}],"correct":["A","B","E"],"pages":[309],"source":"set-2"},{"id":"set2-kJ_5fb0v","fingerprint":"8d31512ce90ebfde","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele manopere iatrogene sunt incriminate în afectarea parodonțiului?","options":[{"id":"A","text":"Instrumentarea endodontică agresivă."},{"id":"B","text":"Realizarea de obturații ocluzale înalte ce duc la traumă ocluzală."},{"id":"C","text":"Coroanele protetice prea scurte care agresează spațiul biologic."},{"id":"D","text":"Obturațiile de compozit nefinisate și rugoase, care creează suprafețe retentive pentru placa bacteriană."},{"id":"E","text":"Șlefuitul intempestiv, subgingival, cu afectarea parodonțiului."}],"correct":["A","B","D","E"],"pages":[310],"source":"set-2"},{"id":"set2-LD95-nJA","fingerprint":"eb16ac7e2f23dd01","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt efectele incongruenței dento-alveolare asupra parodonțiului, în funcție de tipul acesteia?","options":[{"id":"A","text":"În incongruența cu înghesuire papilele interdentare vor fi expuse direct impactului alimentar în timpul masticației."},{"id":"B","text":"În incongruența cu spațiere, septurile și papilele interdentare sunt subțiri și cu troficitate scăzută."},{"id":"C","text":"Incongruența cu înghesuire favorizează retenția plăcii bacteriene prin deficitul de autocurățire și dificultățile de curățire artificială."},{"id":"D","text":"Incongruența cu spațiere este însoțită de fenomene de aplatizare a papilelor interdentare și de atrofie."},{"id":"E","text":"Incongruența cu înghesuire se poate însoți de o reducere a nivelului osos."}],"correct":["C","D","E"],"pages":[309],"source":"set-2"},{"id":"set2-OLX43U0S","fingerprint":"5d43daecd0869523","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele afirmații descriu mecanismele prin care factorii sistemici intervin în patogenia bolii parodontale?","options":[{"id":"A","text":"Previn distrucția țesuturilor parodontale prin inhibarea mediatorilor inflamatori specifici."},{"id":"B","text":"Au capacitatea de a declanșa boala parodontală în absența totală a bacteriilor parodonto-patogene."},{"id":"C","text":"Acționează ca factori predispozanți prin creșterea susceptibilității gazdei."},{"id":"D","text":"Influențează inițierea afecțiunilor parodontale prin dereglarea sintezei și activității mediatorilor inflamatori."},{"id":"E","text":"Cresc prevalența și severitatea bolii printr-un ritm mai accentuat al proceselor distructive."}],"correct":["C","D","E"],"pages":[310],"source":"set-2"},{"id":"set2-35IA6aEX","fingerprint":"84aa1553239dbf09","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este relația dintre bacteriile parodonto-patogene și răspunsul imun al gazdei în inițierea bolii parodontale?","options":[{"id":"A","text":"Organismele cu susceptibilitate scăzută prezintă o distrucție marcată și rapidă a țesuturilor parodontale la primul contact cu agenții patogeni."},{"id":"B","text":"Bacteriile patogene sunt eliminate exclusiv prin intervenție terapeutică mecanică, răspunsul imun fiind irelevant în absența tratamentului."},{"id":"C","text":"Bacteriile parodonto-patogene necesită un răspuns imun susceptibil pentru declanșarea bolii, neputând iniția singure procesul patologic."},{"id":"D","text":"Prezența bacteriilor parodonto-patogene este suficientă pentru declanșarea bolii, indiferent de susceptibilitatea gazdei."},{"id":"E","text":"Un răspuns imuno-inflamator eficient agravează invariabil distrucția parodontală indusă de microorganismele patogene."}],"correct":["C"],"pages":[310],"source":"set-2"},{"id":"set2--pfhw41m","fingerprint":"78f4d10573aa0c64","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele condiții sunt enumerate ca fiind factori sistemici care predispun la apariția bolii parodontale?","options":[{"id":"A","text":"Bolile hematologice"},{"id":"B","text":"Stress-ul și sindroamele psiho-somatice"},{"id":"C","text":"Deficiențele nutriționale"},{"id":"D","text":"Trauma ocluzală"},{"id":"E","text":"Sindroamele genetice"}],"correct":["A","B","C","E"],"pages":[310],"source":"set-2"},{"id":"set2-uuiGDyQU","fingerprint":"948769f4157b2c3b","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Ce consecințe clinice sunt determinate de diferențele de susceptibilitate a organismului gazdă în patologia parodontală?","options":[{"id":"A","text":"Inițierea spontană a bolii parodontale prin mecanisme strict imunitare, în absența oricărei bacterii patogene."},{"id":"B","text":"Lipsa totală de impact clinic în cazul pacienților care prezintă o susceptibilitate crescută."},{"id":"C","text":"Variația răspunsului la tratamentul parodontal în funcție de capacitatea proprie de vindecare."},{"id":"D","text":"Vulnerabilitatea inegală a pacienților la efectele distructive ale patogenilor parodontali."},{"id":"E","text":"Manifestarea unor forme diferite ale bolii în pofida prezenței unor patogeni bacterieni similari."}],"correct":["C","D","E"],"pages":[310],"source":"set-2"},{"id":"set2-B1yjyp0C","fingerprint":"e8d494dafe2ebfa4","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Cum se manifestă clinic la nivel parodontal dereglarea mecanismelor sintezei și activității mediatorilor inflamatori induse de anumite boli sistemice?","options":[{"id":"A","text":"Prin stimularea proceselor de regenerare osoasă tisulară spontană."},{"id":"B","text":"Prin scăderea severității afecțiunilor parodontale preexistente."},{"id":"C","text":"Prin blocarea totală a răspunsului imuno-inflamator local."},{"id":"D","text":"Prin eliminarea rapidă și eficientă a microorganismelor patogene cantonate la nivel subgingival."},{"id":"E","text":"Prin semnele timpurii ale distrucției țesuturilor parodontale."}],"correct":["E"],"pages":[310],"source":"set-2"},{"id":"set2-7U2j_qSO","fingerprint":"d40a65c73657061f","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt criteriile și parametrii care modifică gradul de progresie al parodontitei și aprecierea riscului individual?","options":[{"id":"A","text":"Fumătorul ocazional este definit ca persoana care consumă între 10 și 20 de țigări pe zi."},{"id":"B","text":"Evaluarea controlului glicemic permite modificarea stadiului de severitate a parodontitei, pragul fiind o valoare a hemoglobinei glicozilate de 9%."},{"id":"C","text":"Încadrarea unui pacient în categoria de fost fumător se realizează după o perioadă de abstinență de cel puțin 3 ani."},{"id":"D","text":"Pragul de modificare a gradului de progresie determinat de diabetul zaharat este considerat valoarea de 7% a hemoglobinei glicozilate."},{"id":"E","text":"Consumul zilnic a minimum 10 țigări constituie pragul de modificare a gradului de progresie asociat fumatului."}],"correct":["D","E"],"pages":[310,311,312,313],"source":"set-2"},{"id":"set2-hY7ZN7nR","fingerprint":"2427ee71a442dca5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este mecanismul principal prin care diabetul zaharat slab controlat predispune pacienții la o susceptibilitate crescută față de infecțiile parodontale?","options":[{"id":"A","text":"Îmbunătățirea răspunsului microcirculației la acumularea de placă bacteriană prin hiperemie reactivă susținută."},{"id":"B","text":"Scăderea sintezei de citokine proinflamatorii și a mediatorilor inflamației la nivelul țesuturilor parodontale profunde."},{"id":"C","text":"Alterarea chemotactismului, a aderenței și a fagocitozei la nivelul celulelor polimorfonucleare, monocitelor și macrofagelor."},{"id":"D","text":"Creșterea nivelului de antioxidanți, precum vitamina A și vitamina C, cu favorizarea stresului oxidativ tisular."},{"id":"E","text":"Diminuarea concentrației de oxigen din țesuturile gingivale asociată cu o creștere a numărului total de leucocite și limfocite B."}],"correct":["C"],"pages":[310,311,312,313],"source":"set-2"},{"id":"set2-CSLFCdnb","fingerprint":"4b6299f84bfaa9e9","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care sunt modificările clinice și fiziopatologice caracteristice induse de fumat la nivelul parodonțiului și al răspunsului terapeutic?","options":[{"id":"A","text":"Utilizarea tutunului fără ardere determină o progresie generalizată a bolii parodontale, independent de zona de contact cu produsul de tutun."},{"id":"B","text":"Sângerarea la sondare este mai accentuată la fumători din cauza proliferării vaselor sanguine de la nivel gingival."},{"id":"C","text":"Semnele clinice de inflamație gingivală ca răspuns la acumularea de placă sunt reduse la fumători comparativ cu nefumătorii."},{"id":"D","text":"Concentrația de oxigen din țesuturile gingivale sănătoase este mai redusă la fumători, condiție care se inversează în prezența unei inflamații moderate."},{"id":"E","text":"Câștigul de atașament clinic ca rezultat al detartrajului și planării radiculare este mai redus la fumători față de nefumători."}],"correct":["C","D","E"],"pages":[310,311,312,313],"source":"set-2"},{"id":"set2-hMqw0ns-","fingerprint":"579ec651e281f131","chapterId":"set-2","subchapterId":"set2-4.02","type":"CM","text":"Care dintre următoarele modificări reprezintă efecte sistemice pe termen lung ale fumatului implicate în patogenia bolilor parodontale și a altor afecțiuni generale?","options":[{"id":"A","text":"Reducerea numărului total de leucocite și a celulelor polimorfonucleare din circulația sistemică."},{"id":"B","text":"Creșterea nivelului total al limfocitelor T, fenomen cu semnificație în bronhopneumopatia obstructivă cronică."},{"id":"C","text":"Diminuarea concentrației proteinelor de fază acută, precum proteina C-reactivă și fibrinogenul, la nivel pulmonar."},{"id":"D","text":"Scăderea nivelului de antioxidanți plasmatici, precum vitamina A și vitamina C."},{"id":"E","text":"Creșterea sintezei de citokine proinflamatorii, printre care se numără IL-1α, IL-6 și TNF-α."}],"correct":["B","D","E"],"pages":[310,311,312,313],"source":"set-2"},{"id":"set2-3AuTxsDC","fingerprint":"d33d061d956afaa5","chapterId":"set-2","subchapterId":"set2-4.02","type":"CS","text":"Care este impactul demonstrat al fumatului asupra evoluției bolii parodontale la persoanele tinere?","options":[{"id":"A","text":"Adulții tineri fumători prezintă un risc de 2,9 ori mai mare de a dezvolta parodontită severă comparativ cu cei cu un control glicemic slab."},{"id":"B","text":"Semnele clinice de inflamație sunt direct proporționale cu numărul anilor de fumat, reflectând un răspuns imunitar exagerat la pacienții tineri."},{"id":"C","text":"Prevalența cariilor de suprafață radiculară în treimea cervicală este influențată exclusiv de igiena orală, fiind independentă de numărul anilor de fumat."},{"id":"D","text":"Fumatul este asociat cu o severitate crescută a parodontitei agresive generalizate și determină o probabilitate de 3,8 ori mai mare de apariție a parodontitei la categoria de vârstă 19-30 de ani."},{"id":"E","text":"Indivizii tineri care consumă mai mult de 15 țigări pe zi prezintă un risc diminuat de pierdere a dinților datorită cheratinizării crescute a gingiei."}],"correct":["D"],"pages":[310,311,312,313],"source":"set-2"}];
